//! `lev add` - Install an agent package

use clap::Args;
use std::path::Path;

#[derive(Args)]
pub struct AddArgs {
    /// Path to agent directory, .leviath-bundle file, or registry package name
    #[arg(value_name = "PACKAGE")]
    pub package: String,

    /// Install from registry (URL override)
    #[arg(short, long)]
    pub registry: Option<String>,
}

pub async fn execute(args: AddArgs) -> anyhow::Result<()> {
    tracing::info!(package = %args.package, "Installing agent package");

    let installer = leviath_package::AgentInstaller::new();
    let package_path = Path::new(&args.package);

    if package_path.is_dir() {
        // Directory install: copy directory into ~/.leviath/agents/<name>/
        install_from_dir(package_path)?;
    } else if package_path.exists() || args.package.ends_with(".leviath-bundle") {
        // Bundle file installation
        if !package_path.exists() {
            anyhow::bail!("Package file not found: {}", args.package);
        }
        println!("Installing from bundle: {}", args.package);
        let installed = installer.install(package_path)?;
        println!(
            "Installed agent '{}' v{} to {}",
            installed.name,
            installed.version,
            installed.path.display()
        );
    } else {
        // Registry installation
        let config = crate::config::Config::load()?;
        let registry_url = args
            .registry
            .or_else(|| config.registries.first().cloned())
            .unwrap_or_else(|| "https://leviath.dev/registry".to_string());

        println!(
            "Searching registry {} for '{}'...",
            registry_url, args.package
        );

        let registry = leviath_package::PackageRegistry::new(registry_url);

        let info = registry.get_info(&args.package).await?;
        println!(
            "Found: {} v{} - {}",
            info.name, info.version, info.description
        );

        println!("Downloading...");
        let data = registry.download(&info.name, &info.version).await?;

        let installed = installer.install_from_bytes(&info.name, &data)?;
        println!(
            "Installed agent '{}' v{} to {}",
            installed.name,
            installed.version,
            installed.path.display()
        );
    }

    Ok(())
}

/// Copy a plain agent directory into `~/.leviath/agents/<name>/`.
///
/// The agent name is read from `agent.leviath` in the directory (falling back
/// to the directory's own name).
fn install_from_dir(src: &Path) -> anyhow::Result<()> {
    let manifest_path = src.join("agent.leviath");
    if !manifest_path.exists() {
        anyhow::bail!(
            "No agent.leviath found in '{}'. Is this an agent directory?",
            src.display()
        );
    }

    // Read the manifest to extract the agent name
    let content = std::fs::read_to_string(&manifest_path)?;
    let name = parse_agent_name(&content).unwrap_or_else(|| {
        src.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("unknown")
            .to_string()
    });

    let install_dir = dirs::home_dir()
        .ok_or_else(|| anyhow::anyhow!("Could not determine home directory"))?
        .join(".leviath")
        .join("agents")
        .join(&name);

    if install_dir.exists() {
        println!("Reinstalling agent '{}' (replacing existing)", name);
        std::fs::remove_dir_all(&install_dir)?;
    }

    copy_dir_recursive(src, &install_dir)?;
    println!("Installed agent '{}' to {}", name, install_dir.display());
    println!("Run with:  lev run {} --task \"...\"", name);
    Ok(())
}

/// Recursively copy a directory tree.
fn copy_dir_recursive(src: &Path, dst: &Path) -> anyhow::Result<()> {
    std::fs::create_dir_all(dst)?;
    for entry in std::fs::read_dir(src)? {
        let entry = entry?;
        let src_path = entry.path();
        let dst_path = dst.join(entry.file_name());
        if src_path.is_dir() {
            copy_dir_recursive(&src_path, &dst_path)?;
        } else {
            std::fs::copy(&src_path, &dst_path)?;
        }
    }
    Ok(())
}

/// Parse the agent name from an `agent.leviath` manifest (first `name = "..."` line).
fn parse_agent_name(content: &str) -> Option<String> {
    for line in content.lines() {
        let trimmed = line.trim();
        if let Some(rest) = trimmed.strip_prefix("name") {
            let rest = rest.trim_start_matches(|c: char| c.is_whitespace() || c == '=');
            let name = rest.trim().trim_matches('"');
            if !name.is_empty() {
                return Some(name.to_string());
            }
        }
    }
    None
}

//! `lev create` - Create a new agent blueprint

use clap::Args;
use std::fs;
use std::path::Path;

#[derive(Args)]
pub struct CreateArgs {
    /// Blueprint name
    #[arg(value_name = "NAME")]
    pub name: String,

    /// Starting template (software-engineer, coder, researcher)
    #[arg(short, long, default_value = "software-engineer")]
    pub template: String,
}

pub async fn execute(args: CreateArgs) -> anyhow::Result<()> {
    tracing::info!(name = %args.name, template = %args.template, "Creating agent blueprint");

    let blueprint_dir = Path::new(&args.name);

    if blueprint_dir.exists() {
        anyhow::bail!("Directory '{}' already exists", args.name);
    }

    fs::create_dir_all(blueprint_dir)?;

    let manifest = create_manifest(&args.name, &args.template);
    fs::write(blueprint_dir.join("agent.leviath"), manifest)?;

    fs::write(
        blueprint_dir.join(".gitignore"),
        ".env\n*.leviath-bundle\n.leviath/\n",
    )?;

    fs::write(
        blueprint_dir.join(".env.example"),
        "# Copy this to .env and fill in your API key\n# ANTHROPIC_API_KEY=sk-ant-...\n# OPENAI_API_KEY=sk-...\n# OPENROUTER_API_KEY=sk-or-...\n",
    )?;

    println!("Created blueprint: {}", args.name);
    println!("\nNext steps:");
    println!("  cd {}", args.name);
    println!("  lev run . --task \"Your task here\"");
    println!(
        "  lev add . && lev run {} --task \"Your task here\"",
        args.name
    );

    Ok(())
}

fn create_manifest(name: &str, template: &str) -> String {
    match template {
        "coder" => format!(
            r#"[agent]
name = "{name}"
version = "0.1.0"
description = "A coding assistant blueprint"

[stages.analyze]
mode = "autonomous"
model = {{ provider = "anthropic", model = "claude-sonnet-4-6" }}
description = "Understand the task and plan the implementation"
available_tools = ["read_file", "list_dir"]
max_iterations = 15
system_prompt = """
Analyze the coding task and produce a concise implementation plan.
"""

[stages.implement]
mode = "autonomous"
model = {{ provider = "anthropic", model = "claude-sonnet-4-6" }}
description = "Write code according to the plan"
available_tools = ["write_file", "read_file", "edit_file", "list_dir", "bash"]
max_iterations = 50
system_prompt = """
Implement the plan. Create all necessary files and verify with bash.
"""

[context.regions]
task         = {{ kind = "pinned",          max_tokens = 2000 }}
codebase     = {{ kind = "temporary",       max_tokens = 30000 }}
conversation = {{ kind = "sliding_window",  max_items = 20, max_tokens = 15000 }}
scratch      = {{ kind = "clearable",       max_tokens = 10000 }}
"#,
            name = name
        ),

        "researcher" => format!(
            r#"[agent]
name = "{name}"
version = "0.1.0"
description = "A research assistant blueprint"

[stages.gather]
mode = "autonomous"
model = {{ provider = "anthropic", model = "claude-sonnet-4-6" }}
description = "Gather relevant information"
available_tools = ["read_file", "list_dir", "bash"]
max_iterations = 20

[stages.synthesize]
mode = "interactive"
model = {{ provider = "anthropic", model = "claude-sonnet-4-6" }}
description = "Synthesize findings and discuss with user"
available_tools = ["read_file", "list_dir"]
max_iterations = 15

[context.regions]
objective    = {{ kind = "pinned",          max_tokens = 2000 }}
sources      = {{ kind = "temporary",       max_tokens = 40000 }}
findings     = {{ kind = "compacting",      threshold_tokens = 8000, max_tokens = 15000 }}
conversation = {{ kind = "sliding_window",  max_items = 15, max_tokens = 12000 }}
scratch      = {{ kind = "clearable",       max_tokens = 8000 }}
"#,
            name = name
        ),

        _ => format!(
            r#"[agent]
name = "{name}"
version = "0.1.0"
description = "A simple agent blueprint"

[stages.main]
mode = "autonomous"
model = {{ provider = "anthropic", model = "claude-sonnet-4-6" }}
description = "Main execution stage"
available_tools = ["read_file", "list_dir", "write_file", "bash"]
max_iterations = 30
system_prompt = """
You are a helpful agent. Complete the task thoroughly.
"""

[context.regions]
system       = {{ kind = "pinned",         max_tokens = 2000 }}
conversation = {{ kind = "sliding_window", max_items = 10, max_tokens = 10000 }}
scratch      = {{ kind = "clearable",      max_tokens = 5000 }}
"#,
            name = name
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_template_is_valid_toml() {
        let manifest = create_manifest("test-agent", "software-engineer");
        let parsed: toml::Value = toml::from_str(&manifest).unwrap();
        let agent = parsed.get("agent").expect("should have [agent] section");
        assert_eq!(agent.get("name").unwrap().as_str().unwrap(), "test-agent");
        assert_eq!(agent.get("version").unwrap().as_str().unwrap(), "0.1.0");
    }

    #[test]
    fn coder_template_is_valid_toml() {
        let manifest = create_manifest("my-coder", "coder");
        let parsed: toml::Value = toml::from_str(&manifest).unwrap();
        let agent = parsed.get("agent").unwrap();
        assert_eq!(agent.get("name").unwrap().as_str().unwrap(), "my-coder");
        assert!(parsed.get("stages").is_some());
    }

    #[test]
    fn researcher_template_is_valid_toml() {
        let manifest = create_manifest("my-researcher", "researcher");
        let parsed: toml::Value = toml::from_str(&manifest).unwrap();
        let agent = parsed.get("agent").unwrap();
        assert_eq!(
            agent.get("name").unwrap().as_str().unwrap(),
            "my-researcher"
        );
    }

    #[test]
    fn unknown_template_falls_back_to_default() {
        let manifest = create_manifest("x", "nonexistent-template");
        let parsed: toml::Value = toml::from_str(&manifest).unwrap();
        let stages = parsed.get("stages").unwrap().as_table().unwrap();
        // Default template has a single "main" stage
        assert!(stages.contains_key("main"));
    }

    #[test]
    fn coder_template_has_analyze_and_implement_stages() {
        let manifest = create_manifest("x", "coder");
        let parsed: toml::Value = toml::from_str(&manifest).unwrap();
        let stages = parsed.get("stages").unwrap().as_table().unwrap();
        assert!(stages.contains_key("analyze"));
        assert!(stages.contains_key("implement"));
    }

    #[test]
    fn researcher_template_has_gather_and_synthesize_stages() {
        let manifest = create_manifest("x", "researcher");
        let parsed: toml::Value = toml::from_str(&manifest).unwrap();
        let stages = parsed.get("stages").unwrap().as_table().unwrap();
        assert!(stages.contains_key("gather"));
        assert!(stages.contains_key("synthesize"));
    }

    #[test]
    fn template_embeds_agent_name() {
        let manifest = create_manifest("special-name-123", "coder");
        assert!(manifest.contains("special-name-123"));
    }

    #[test]
    fn all_templates_have_context_regions() {
        for template in &["software-engineer", "coder", "researcher"] {
            let manifest = create_manifest("test", template);
            let parsed: toml::Value = toml::from_str(&manifest).unwrap();
            assert!(
                parsed.get("context").is_some(),
                "template '{}' missing [context]",
                template
            );
        }
    }
}

//! Graph transition info for non-linear (graph-mode) agents.

use leviath_core::{EdgeTransform, TransitionCondition};

/// Cached transition info parsed from the agent's blueprint.
#[derive(Debug, Clone)]
pub(super) struct GraphTransitionInfo {
    /// Map: source_stage → Vec<(target_stage, hint, condition_label, transform_label)>
    pub(super) edges: std::collections::HashMap<String, Vec<GraphEdge>>,
    /// Entry stage name
    pub(super) entry_stage: String,
    /// All stage names in definition order
    pub(super) stage_names: Vec<String>,
}

#[derive(Debug, Clone)]
pub(super) struct GraphEdge {
    pub(super) target: String,
    pub(super) hint: Option<String>,
    pub(super) condition: String,
    #[allow(dead_code)]
    pub(super) transform: String,
}

/// Load graph transition info from an agent manifest directory.
/// Returns `None` for linear agents or if the manifest can't be read/parsed.
pub(super) fn load_graph_info(agent_path: &str) -> Option<GraphTransitionInfo> {
    let manifest_path = std::path::Path::new(agent_path).join("agent.leviath");
    let content = std::fs::read_to_string(&manifest_path).ok()?;
    let blueprint = crate::commands::run::parse_manifest_public(&content).ok()?;

    // Check if any stage has transitions (graph mode)
    let is_graph = blueprint.stages.iter().any(|s| s.transitions.is_some());
    if !is_graph {
        return None;
    }

    let mut edges = std::collections::HashMap::new();
    let stage_names: Vec<String> = blueprint.stages.iter().map(|s| s.name.clone()).collect();

    for stage in &blueprint.stages {
        if let Some(ref transitions) = stage.transitions {
            let stage_edges: Vec<GraphEdge> = transitions
                .iter()
                .map(|(target, edge)| {
                    let condition = match &edge.condition {
                        TransitionCondition::Always => "always".to_string(),
                        TransitionCondition::Error => "error".to_string(),
                        TransitionCondition::MaxIterations => "max_iterations".to_string(),
                        TransitionCondition::LlmChoice => "llm_choice".to_string(),
                        TransitionCondition::Custom(s) => s.clone(),
                    };
                    let transform = match &edge.transform {
                        EdgeTransform::Direct => "direct".to_string(),
                        EdgeTransform::Clear => "clear".to_string(),
                        EdgeTransform::Compact { .. } => "compact".to_string(),
                        EdgeTransform::Custom { .. } => "custom".to_string(),
                    };
                    GraphEdge {
                        target: target.clone(),
                        hint: edge.hint.clone(),
                        condition,
                        transform,
                    }
                })
                .collect();
            edges.insert(stage.name.clone(), stage_edges);
        }
    }

    Some(GraphTransitionInfo {
        edges,
        entry_stage: blueprint.resolve_entry_stage_name(),
        stage_names,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn graph_edge_debug_format() {
        let edge = GraphEdge {
            target: "plan".to_string(),
            hint: Some("on success".to_string()),
            condition: "always".to_string(),
            transform: "direct".to_string(),
        };
        let dbg = format!("{:?}", edge);
        assert!(dbg.contains("plan"));
        assert!(dbg.contains("on success"));
    }

    #[test]
    fn graph_transition_info_empty() {
        let info = GraphTransitionInfo {
            edges: std::collections::HashMap::new(),
            entry_stage: "main".to_string(),
            stage_names: vec!["main".to_string()],
        };
        assert_eq!(info.stage_names.len(), 1);
        assert!(info.edges.is_empty());
    }

    #[test]
    fn graph_transition_info_with_edges() {
        let mut edges = std::collections::HashMap::new();
        edges.insert(
            "plan".to_string(),
            vec![GraphEdge {
                target: "implement".to_string(),
                hint: None,
                condition: "always".to_string(),
                transform: "direct".to_string(),
            }],
        );
        edges.insert(
            "implement".to_string(),
            vec![
                GraphEdge {
                    target: "review".to_string(),
                    hint: Some("done".to_string()),
                    condition: "llm_choice".to_string(),
                    transform: "compact".to_string(),
                },
                GraphEdge {
                    target: "plan".to_string(),
                    hint: Some("needs rework".to_string()),
                    condition: "llm_choice".to_string(),
                    transform: "clear".to_string(),
                },
            ],
        );
        let info = GraphTransitionInfo {
            edges,
            entry_stage: "plan".to_string(),
            stage_names: vec![
                "plan".to_string(),
                "implement".to_string(),
                "review".to_string(),
            ],
        };
        assert_eq!(info.stage_names.len(), 3);
        assert_eq!(info.entry_stage, "plan");
        assert_eq!(info.edges.get("plan").unwrap().len(), 1);
        assert_eq!(info.edges.get("implement").unwrap().len(), 2);
        assert!(!info.edges.contains_key("review"));
    }

    #[test]
    fn load_graph_info_nonexistent_path() {
        let result = load_graph_info("/nonexistent/path/to/agent");
        assert!(result.is_none());
    }

    #[test]
    fn graph_edge_clone() {
        let edge = GraphEdge {
            target: "x".to_string(),
            hint: None,
            condition: "always".to_string(),
            transform: "direct".to_string(),
        };
        let cloned = edge.clone();
        assert_eq!(cloned.target, "x");
    }

    #[test]
    fn graph_transition_info_clone() {
        let info = GraphTransitionInfo {
            edges: std::collections::HashMap::new(),
            entry_stage: "start".to_string(),
            stage_names: vec!["start".to_string(), "end".to_string()],
        };
        let cloned = info.clone();
        assert_eq!(cloned.entry_stage, "start");
        assert_eq!(cloned.stage_names.len(), 2);
    }
}

//! Pure utility functions used across the dashboard.

use crate::runstate;

/// Format a Unix timestamp as a relative time string ("just now", "2m ago", "1h ago").
pub(super) fn relative_time(ts: i64) -> String {
    if ts == 0 {
        return "—".to_string();
    }
    use std::time::{SystemTime, UNIX_EPOCH};
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let secs = (now - ts).max(0) as u64;
    if secs < 10 {
        "just now".to_string()
    } else if secs < 60 {
        format!("{}s ago", secs)
    } else if secs < 3600 {
        let m = secs / 60;
        format!("{}m ago", m)
    } else if secs < 86400 {
        let h = secs / 3600;
        let m = (secs % 3600) / 60;
        if m == 0 {
            format!("{}h ago", h)
        } else {
            format!("{}h{}m ago", h, m)
        }
    } else {
        let d = secs / 86400;
        format!("{}d ago", d)
    }
}

/// After SIGTERMing a background worker, immediately write Cancelled to meta.json
/// so the next sync tick doesn't revert the status.
pub(super) fn kill_write_cancelled(run_id: &str) {
    if let Ok(mut meta) = runstate::read_meta(run_id) {
        meta.status = runstate::RunStatus::Cancelled;
        meta.touch();
        let _ = runstate::write_meta(&meta);
    }
}

pub(super) fn truncate(s: &str, max: usize) -> String {
    let s = s.trim();
    if s.len() <= max {
        s.to_string()
    } else {
        format!("{}…", &s[..max])
    }
}

/// Format a token count in compact style: ≥1000 → "21k", else raw.
pub(super) fn format_tokens(n: usize) -> String {
    if n >= 1_000_000 {
        format!("{}M", n / 1_000_000)
    } else if n >= 1_000 {
        format!("{}k", n / 1_000)
    } else {
        n.to_string()
    }
}

/// Format elapsed seconds as a human-readable duration string.
pub(super) fn elapsed_str(started_at: i64) -> String {
    if started_at == 0 {
        return "—".to_string();
    }
    use std::time::{SystemTime, UNIX_EPOCH};
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let secs = (now - started_at).max(0) as u64;
    if secs < 60 {
        format!("{}s", secs)
    } else if secs < 3600 {
        format!("{}m{}s", secs / 60, secs % 60)
    } else {
        format!("{}h{}m", secs / 3600, (secs % 3600) / 60)
    }
}

/// Format elapsed seconds from `started_at` up to `until` (not current time).
pub(super) fn elapsed_str_until(started_at: i64, until: i64) -> String {
    if started_at == 0 {
        return "—".to_string();
    }
    let secs = (until - started_at).max(0) as u64;
    if secs < 60 {
        format!("{}s", secs)
    } else if secs < 3600 {
        format!("{}m{}s", secs / 60, secs % 60)
    } else {
        format!("{}h{}m", secs / 3600, (secs % 3600) / 60)
    }
}

/// Copy `text` to the system clipboard.  Returns `true` on success.
///
/// Strategy (in order):
/// 1. `pbcopy` (macOS)
/// 2. `xclip -selection clipboard` (Linux X11)
/// 3. `wl-copy` (Linux Wayland)
/// 4. OSC52 via /dev/tty → stdout fallback
pub(super) fn yank_to_clipboard(text: &str) -> bool {
    use std::io::Write as IoWrite;
    use std::process::{Command, Stdio};

    // Try native clipboard tools first — most reliable
    let clipboard_cmds: &[(&str, &[&str])] = &[
        ("pbcopy", &[]),
        ("xclip", &["-selection", "clipboard"]),
        ("wl-copy", &[]),
    ];
    for (cmd, args) in clipboard_cmds {
        if let Ok(mut child) = Command::new(cmd)
            .args(*args)
            .stdin(Stdio::piped())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
        {
            if let Some(stdin) = child.stdin.as_mut() {
                let _ = stdin.write_all(text.as_bytes());
            }
            if child.wait().map(|s| s.success()).unwrap_or(false) {
                return true;
            }
        }
    }

    // Fall back to OSC52
    osc52_yank_raw(text)
}

/// Yank via the OSC52 terminal escape sequence — last-resort fallback.
pub(super) fn osc52_yank_raw(text: &str) -> bool {
    use std::io::Write;
    // Base64-encode the content
    let encoded = {
        use std::fmt::Write as FmtWrite;
        let bytes = text.as_bytes();
        let mut out = String::with_capacity((bytes.len() * 4 / 3) + 8);
        const TABLE: &[u8; 64] =
            b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        let mut i = 0;
        while i + 3 <= bytes.len() {
            let b0 = bytes[i] as usize;
            let b1 = bytes[i + 1] as usize;
            let b2 = bytes[i + 2] as usize;
            let _ = FmtWrite::write_char(&mut out, TABLE[b0 >> 2] as char);
            let _ = FmtWrite::write_char(&mut out, TABLE[((b0 & 3) << 4) | (b1 >> 4)] as char);
            let _ = FmtWrite::write_char(&mut out, TABLE[((b1 & 0xf) << 2) | (b2 >> 6)] as char);
            let _ = FmtWrite::write_char(&mut out, TABLE[b2 & 0x3f] as char);
            i += 3;
        }
        let rem = bytes.len() - i;
        if rem == 1 {
            let b0 = bytes[i] as usize;
            let _ = FmtWrite::write_char(&mut out, TABLE[b0 >> 2] as char);
            let _ = FmtWrite::write_char(&mut out, TABLE[(b0 & 3) << 4] as char);
            out.push_str("==");
        } else if rem == 2 {
            let b0 = bytes[i] as usize;
            let b1 = bytes[i + 1] as usize;
            let _ = FmtWrite::write_char(&mut out, TABLE[b0 >> 2] as char);
            let _ = FmtWrite::write_char(&mut out, TABLE[((b0 & 3) << 4) | (b1 >> 4)] as char);
            let _ = FmtWrite::write_char(&mut out, TABLE[(b1 & 0xf) << 2] as char);
            out.push('=');
        }
        out
    };
    let osc = format!("\x1b]52;c;{}\x07", encoded);
    // Write directly to /dev/tty to bypass ratatui's raw mode stdout handling.
    #[cfg(unix)]
    {
        if let Ok(mut tty) = std::fs::OpenOptions::new().write(true).open("/dev/tty") {
            let _ = tty.write_all(osc.as_bytes());
            let _ = tty.flush();
            return true;
        }
    }
    // Fallback: write to stdout
    let mut stdout = std::io::stdout();
    let _ = stdout.write_all(osc.as_bytes());
    let _ = stdout.flush();
    true
}

