//! Background polling loop for change detection and event broadcasting.

use std::collections::HashMap;
use std::time::Duration;

use tracing::error;

use super::types::*;
use crate::interaction;
use crate::runstate::{self, RunStatus};

/// Cached state for change detection.
struct PollState {
    /// run_id → (status_string, iteration, prompt_tokens, completion_tokens)
    last_status: HashMap<String, (String, usize, usize, usize)>,
    /// run_id → total_tokens from last context snapshot
    last_context_tokens: HashMap<String, usize>,
    /// run_id → whether we saw a pending interaction
    last_pending: HashMap<String, bool>,
    /// run_id → set of run_ids we have already fired callbacks for
    callback_fired: HashMap<String, bool>,
}

pub(super) async fn polling_loop(state: AppState) {
    let mut poll = PollState {
        last_status: HashMap::new(),
        last_context_tokens: HashMap::new(),
        last_pending: HashMap::new(),
        callback_fired: HashMap::new(),
    };

    let client = reqwest::Client::new();

    loop {
        tokio::time::sleep(Duration::from_millis(200)).await;

        let runs = runstate::list_runs();

        for meta in &runs {
            let status_str = format!("{}", meta.status);
            let key = (
                status_str.clone(),
                meta.iteration,
                meta.prompt_tokens,
                meta.completion_tokens,
            );

            // Detect meta.json changes
            if poll.last_status.get(&meta.run_id) != Some(&key) {
                let _ = state.event_tx.send(ServerEvent::AgentStatus {
                    agent_id: meta.agent_name.clone(),
                    run_id: meta.run_id.clone(),
                    status: status_str.clone(),
                    stage: meta.current_stage.clone(),
                    iteration: meta.iteration,
                    accepts_messages: true, // default; stage-level control via agent state
                });

                // Token update
                let _ = state.event_tx.send(ServerEvent::Tokens {
                    agent_id: meta.agent_name.clone(),
                    run_id: meta.run_id.clone(),
                    prompt_tokens: meta.prompt_tokens,
                    completion_tokens: meta.completion_tokens,
                });

                // Detect completion
                let was_terminal = poll
                    .last_status
                    .get(&meta.run_id)
                    .map(|(s, _, _, _)| s == "Complete" || s == "Error" || s == "Cancelled")
                    .unwrap_or(false);

                if !was_terminal
                    && (meta.status == RunStatus::Complete || meta.status == RunStatus::Error)
                {
                    let _ = state.event_tx.send(ServerEvent::AgentCompleted {
                        agent_id: meta.agent_name.clone(),
                        run_id: meta.run_id.clone(),
                        status: status_str.clone(),
                        result: meta.error.clone(),
                    });

                    // Fire webhook callback if configured
                    if let Some(ref url) = meta.callback_url {
                        if !poll
                            .callback_fired
                            .get(&meta.run_id)
                            .copied()
                            .unwrap_or(false)
                        {
                            poll.callback_fired.insert(meta.run_id.clone(), true);
                            let payload = serde_json::json!({
                                "event": "agent_completed",
                                "run_id": meta.run_id,
                                "agent_id": meta.agent_name,
                                "status": status_str,
                                "result": meta.error,
                                "metadata": meta.metadata,
                                "tokens": {
                                    "prompt": meta.prompt_tokens,
                                    "completion": meta.completion_tokens,
                                }
                            });
                            let client = client.clone();
                            let url = url.clone();
                            tokio::spawn(async move {
                                if let Err(e) = client.post(&url).json(&payload).send().await {
                                    error!(url = %url, error = %e, "Webhook callback failed");
                                }
                            });
                        }
                    }
                }

                poll.last_status.insert(meta.run_id.clone(), key);
            }

            // Detect context.json changes
            if let Some(ctx) = runstate::read_context_snapshot(&meta.run_id) {
                let prev = poll.last_context_tokens.get(&meta.run_id).copied();
                if prev != Some(ctx.total_tokens) {
                    let _ = state.event_tx.send(ServerEvent::ContextUpdate {
                        agent_id: meta.agent_name.clone(),
                        run_id: meta.run_id.clone(),
                        total_tokens: ctx.total_tokens,
                        max_tokens: ctx.max_tokens,
                    });
                    poll.last_context_tokens
                        .insert(meta.run_id.clone(), ctx.total_tokens);
                }
            }

            // Detect pending.json
            let has_pending = interaction::read_request(&meta.run_id).is_some();
            let had_pending = poll
                .last_pending
                .get(&meta.run_id)
                .copied()
                .unwrap_or(false);
            if has_pending && !had_pending {
                if let Some(req) = interaction::read_request(&meta.run_id) {
                    let val = serde_json::to_value(&req).unwrap_or(serde_json::Value::Null);
                    let _ = state.event_tx.send(ServerEvent::InteractionNeeded {
                        agent_id: meta.agent_name.clone(),
                        run_id: meta.run_id.clone(),
                        request: val,
                    });
                }
            }
            poll.last_pending.insert(meta.run_id.clone(), has_pending);
        }

        // Clean up old entries for runs that no longer exist
        let run_ids: std::collections::HashSet<String> =
            runs.iter().map(|r| r.run_id.clone()).collect();
        poll.last_status.retain(|k, _| run_ids.contains(k));
        poll.last_context_tokens.retain(|k, _| run_ids.contains(k));
        poll.last_pending.retain(|k, _| run_ids.contains(k));
    }
}

//! Agent hierarchy tree building and endpoints.

use axum::extract::Path as AxumPath;
use axum::http::StatusCode;
use axum::response::Json;

use super::types::*;
use crate::runstate::{self, RunMeta};

pub(super) fn build_tree(runs: &[RunMeta], parent_id: Option<&str>) -> Vec<AgentTreeNode> {
    runs.iter()
        .filter(|r| r.parent_run_id.as_deref() == parent_id)
        .map(|r| {
            let children = build_tree(runs, Some(&r.run_id));
            AgentTreeNode {
                run_id: r.run_id.clone(),
                agent_name: r.agent_name.clone(),
                status: format!("{}", r.status),
                stage: r.current_stage.clone(),
                iteration: r.iteration,
                prompt_tokens: r.prompt_tokens,
                completion_tokens: r.completion_tokens,
                children,
            }
        })
        .collect()
}

pub(super) fn build_tree_status(runs: &[RunMeta], parent_id: Option<&str>) -> Vec<TreeStatusNode> {
    runs.iter()
        .filter(|r| r.parent_run_id.as_deref() == parent_id)
        .map(|r| {
            let children = build_tree_status(runs, Some(&r.run_id));
            let subtree_prompt: usize = r.prompt_tokens
                + children
                    .iter()
                    .map(|c| c.subtree_prompt_tokens)
                    .sum::<usize>();
            let subtree_completion: usize = r.completion_tokens
                + children
                    .iter()
                    .map(|c| c.subtree_completion_tokens)
                    .sum::<usize>();
            TreeStatusNode {
                run_id: r.run_id.clone(),
                agent_name: r.agent_name.clone(),
                status: format!("{}", r.status),
                stage: r.current_stage.clone(),
                prompt_tokens: r.prompt_tokens,
                completion_tokens: r.completion_tokens,
                subtree_prompt_tokens: subtree_prompt,
                subtree_completion_tokens: subtree_completion,
                children,
            }
        })
        .collect()
}

pub(super) async fn agents_tree() -> Json<Vec<AgentTreeNode>> {
    let runs = runstate::list_runs();
    let tree = build_tree(&runs, None);
    Json(tree)
}

pub(super) async fn agent_tree_status(
    AxumPath(id): AxumPath<String>,
) -> Result<Json<TreeStatusNode>, (StatusCode, Json<ErrorResponse>)> {
    let runs = runstate::list_runs();
    let root = runs.iter().find(|r| r.run_id == id).ok_or((
        StatusCode::NOT_FOUND,
        Json(ErrorResponse {
            error: format!("Agent run '{}' not found", id),
        }),
    ))?;

    let children = build_tree_status(&runs, Some(&id));
    let subtree_prompt: usize = root.prompt_tokens
        + children
            .iter()
            .map(|c| c.subtree_prompt_tokens)
            .sum::<usize>();
    let subtree_completion: usize = root.completion_tokens
        + children
            .iter()
            .map(|c| c.subtree_completion_tokens)
            .sum::<usize>();

    Ok(Json(TreeStatusNode {
        run_id: root.run_id.clone(),
        agent_name: root.agent_name.clone(),
        status: format!("{}", root.status),
        stage: root.current_stage.clone(),
        prompt_tokens: root.prompt_tokens,
        completion_tokens: root.completion_tokens,
        subtree_prompt_tokens: subtree_prompt,
        subtree_completion_tokens: subtree_completion,
        children,
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn make_meta(id: &str, name: &str, parent: Option<&str>) -> RunMeta {
        let mut meta = RunMeta::new(
            id.to_string(),
            name.to_string(),
            "/path".to_string(),
            "task".to_string(),
            None,
            "/work".to_string(),
            1,
        );
        meta.parent_run_id = parent.map(|s| s.to_string());
        meta
    }

    #[test]
    fn build_tree_empty() {
        let runs: Vec<RunMeta> = vec![];
        let tree = build_tree(&runs, None);
        assert!(tree.is_empty());
    }

    #[test]
    fn build_tree_single_root() {
        let runs = vec![make_meta("run-1", "agent-a", None)];
        let tree = build_tree(&runs, None);
        assert_eq!(tree.len(), 1);
        assert_eq!(tree[0].run_id, "run-1");
        assert!(tree[0].children.is_empty());
    }

    #[test]
    fn build_tree_parent_child() {
        let runs = vec![
            make_meta("parent", "agent-a", None),
            make_meta("child", "agent-b", Some("parent")),
        ];
        let tree = build_tree(&runs, None);
        assert_eq!(tree.len(), 1);
        assert_eq!(tree[0].run_id, "parent");
        assert_eq!(tree[0].children.len(), 1);
        assert_eq!(tree[0].children[0].run_id, "child");
    }

    #[test]
    fn build_tree_multiple_roots() {
        let runs = vec![
            make_meta("root-1", "a", None),
            make_meta("root-2", "b", None),
        ];
        let tree = build_tree(&runs, None);
        assert_eq!(tree.len(), 2);
    }

    #[test]
    fn build_tree_nested() {
        let runs = vec![
            make_meta("r", "a", None),
            make_meta("c1", "b", Some("r")),
            make_meta("c2", "c", Some("r")),
            make_meta("gc", "d", Some("c1")),
        ];
        let tree = build_tree(&runs, None);
        assert_eq!(tree.len(), 1);
        assert_eq!(tree[0].children.len(), 2);
        let c1 = &tree[0].children[0];
        assert_eq!(c1.run_id, "c1");
        assert_eq!(c1.children.len(), 1);
        assert_eq!(c1.children[0].run_id, "gc");
    }

    #[test]
    fn build_tree_status_empty() {
        let runs: Vec<RunMeta> = vec![];
        let tree = build_tree_status(&runs, None);
        assert!(tree.is_empty());
    }

    #[test]
    fn build_tree_status_aggregates_tokens() {
        let mut parent = make_meta("p", "a", None);
        parent.prompt_tokens = 10;
        parent.completion_tokens = 5;
        let mut child = make_meta("c", "b", Some("p"));
        child.prompt_tokens = 100;
        child.completion_tokens = 50;
        let runs = vec![parent, child];
        let tree = build_tree_status(&runs, None);
        assert_eq!(tree.len(), 1);
        assert_eq!(tree[0].subtree_prompt_tokens, 110); // 10 + 100
        assert_eq!(tree[0].subtree_completion_tokens, 55); // 5 + 50
    }

    #[test]
    fn build_tree_status_deep_aggregation() {
        let mut root = make_meta("r", "a", None);
        root.prompt_tokens = 10;
        let mut child = make_meta("c", "b", Some("r"));
        child.prompt_tokens = 20;
        let mut grandchild = make_meta("gc", "c", Some("c"));
        grandchild.prompt_tokens = 30;
        let runs = vec![root, child, grandchild];
        let tree = build_tree_status(&runs, None);
        assert_eq!(tree[0].subtree_prompt_tokens, 60); // 10 + 20 + 30
    }

    #[test]
    fn build_tree_from_subtree() {
        let runs = vec![
            make_meta("r", "a", None),
            make_meta("c1", "b", Some("r")),
            make_meta("c2", "c", Some("r")),
        ];
        // Build from a specific parent
        let subtree = build_tree(&runs, Some("r"));
        assert_eq!(subtree.len(), 2);
    }
}

//! Shared types: ServerEvent, AppState, request/response structs, error types.

use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::Arc;

use clap::Args;
use serde::{Deserialize, Serialize};
use tokio::sync::broadcast;

use crate::config::Config;

// ─── CLI ─────────────────────────────────────────────────────────────────────

#[derive(Args)]
pub struct ServeArgs {
    /// Port to listen on
    #[arg(short, long, default_value = "3000")]
    pub port: u16,

    /// Host to bind to
    #[arg(short = 'H', long, default_value = "127.0.0.1")]
    pub host: String,

    /// Allow CORS from origin (default: *)
    #[arg(long, default_value = "*")]
    pub cors: String,
}

// ─── Shared state ────────────────────────────────────────────────────────────

/// Events broadcast to WebSocket subscribers.
#[derive(Debug, Clone, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
#[allow(dead_code)]
pub enum ServerEvent {
    AgentStatus {
        agent_id: String,
        run_id: String,
        status: String,
        stage: String,
        iteration: usize,
        accepts_messages: bool,
    },
    ContextUpdate {
        agent_id: String,
        run_id: String,
        total_tokens: usize,
        max_tokens: usize,
    },
    Log {
        agent_id: String,
        run_id: String,
        line: String,
    },
    InteractionNeeded {
        agent_id: String,
        run_id: String,
        request: serde_json::Value,
    },
    AgentSpawned {
        agent_id: String,
        run_id: String,
        parent_id: Option<String>,
        blueprint: String,
    },
    AgentCompleted {
        agent_id: String,
        run_id: String,
        status: String,
        result: Option<String>,
    },
    Tokens {
        agent_id: String,
        run_id: String,
        prompt_tokens: usize,
        completion_tokens: usize,
    },
}

#[derive(Clone)]
pub struct AppState {
    pub(super) config: Arc<Config>,
    pub(super) event_tx: broadcast::Sender<ServerEvent>,
}

