//! WebSocket endpoints and connection handling.

use axum::extract::ws::{Message, WebSocket};
use axum::extract::{Path as AxumPath, State, WebSocketUpgrade};
use axum::response::IntoResponse;
use tokio::sync::broadcast;
use tracing::warn;

use super::types::*;

pub(super) async fn ws_global(
    State(state): State<AppState>,
    ws: WebSocketUpgrade,
) -> impl IntoResponse {
    ws.on_upgrade(move |socket| handle_ws(socket, state.event_tx, None))
}

pub(super) async fn ws_agent(
    State(state): State<AppState>,
    AxumPath(id): AxumPath<String>,
    ws: WebSocketUpgrade,
) -> impl IntoResponse {
    ws.on_upgrade(move |socket| handle_ws(socket, state.event_tx, Some(id)))
}

async fn handle_ws(
    mut socket: WebSocket,
    event_tx: broadcast::Sender<ServerEvent>,
    filter_run_id: Option<String>,
) {
    let mut rx = event_tx.subscribe();

    loop {
        tokio::select! {
            event = rx.recv() => {
                match event {
                    Ok(ev) => {
                        // If filtering by run_id, skip non-matching events
                        if let Some(ref filter) = filter_run_id {
                            let event_run_id = match &ev {
                                ServerEvent::AgentStatus { run_id, .. } => run_id,
                                ServerEvent::ContextUpdate { run_id, .. } => run_id,
                                ServerEvent::Log { run_id, .. } => run_id,
                                ServerEvent::InteractionNeeded { run_id, .. } => run_id,
                                ServerEvent::AgentSpawned { run_id, .. } => run_id,
                                ServerEvent::AgentCompleted { run_id, .. } => run_id,
                                ServerEvent::Tokens { run_id, .. } => run_id,
                            };
                            if event_run_id != filter {
                                continue;
                            }
                        }

                        if let Ok(json) = serde_json::to_string(&ev) {
                            if socket.send(Message::Text(json.into())).await.is_err() {
                                break;
                            }
                        }
                    }
                    Err(broadcast::error::RecvError::Lagged(n)) => {
                        warn!("WebSocket subscriber lagged by {} events", n);
                    }
                    Err(broadcast::error::RecvError::Closed) => break,
                }
            }
            msg = socket.recv() => {
                match msg {
                    Some(Ok(Message::Close(_))) | None => break,
                    _ => {} // Ignore other client messages
                }
            }
        }
    }
}

//! `lev setup` - Interactive configuration wizard

use clap::Args;
use std::io::{self, Write};

use crate::config::Config;

#[derive(Args)]
pub struct SetupArgs {
    /// Run non-interactively using only flag values (useful for scripting)
    #[arg(long)]
    pub non_interactive: bool,

    /// Anthropic API key
    #[arg(long)]
    pub anthropic_key: Option<String>,

    /// OpenAI API key
    #[arg(long)]
    pub openai_key: Option<String>,

    /// Google AI (Gemini) API key
    #[arg(long)]
    pub google_key: Option<String>,

    /// OpenRouter API key
    #[arg(long)]
    pub openrouter_key: Option<String>,

    /// Ollama base URL (default: http://localhost:11434)
    #[arg(long)]
    pub ollama_url: Option<String>,

    /// Default model override (e.g. claude-sonnet-4-6)
    #[arg(long)]
    pub default_model: Option<String>,
}

pub async fn execute(args: SetupArgs) -> anyhow::Result<()> {
    // Load existing config so we can preserve existing values as defaults
    let mut config = Config::load().unwrap_or_default();

    if args.non_interactive {
        apply_flags(&mut config, &args);
        config.save()?;
        println!("Config saved to {}", Config::config_path().display());
        return Ok(());
    }

    println!("Leviath Setup");
    println!("─────────────────────────────────────────");
    println!("Press Enter to keep the current value shown in [brackets].");
    println!("Type a value and press Enter to update it.");
    println!("Type 'clear' to remove a stored value.");
    println!();

    // Anthropic API key
    let current_anthropic = config.providers.anthropic_api_key.as_deref().map(redact);
    config.providers.anthropic_api_key = prompt_secret(
        "Anthropic API key",
        "sk-ant-...",
        config.providers.anthropic_api_key.as_deref(),
        current_anthropic.as_deref(),
    )?;

    // OpenAI API key
    let current_openai = config.providers.openai_api_key.as_deref().map(redact);
    config.providers.openai_api_key = prompt_secret(
        "OpenAI API key",
        "sk-...",
        config.providers.openai_api_key.as_deref(),
        current_openai.as_deref(),
    )?;

    // Google AI (Gemini) API key
    let current_google = config.providers.google_api_key.as_deref().map(redact);
    config.providers.google_api_key = prompt_secret(
        "Google AI (Gemini) API key",
        "AIza...",
        config.providers.google_api_key.as_deref(),
        current_google.as_deref(),
    )?;

    // OpenRouter API key
    let current_or = config.openrouter_api_key.as_deref().map(redact);
    config.openrouter_api_key = prompt_secret(
        "OpenRouter API key",
        "sk-or-...",
        config.openrouter_api_key.as_deref(),
        current_or.as_deref(),
    )?;

    // Ollama URL
    let default_ollama = "http://localhost:11434";
    let current_ollama = config.ollama_base_url.as_deref().unwrap_or(default_ollama);
    let ollama_input = prompt_plain("Ollama base URL", current_ollama)?;
    config.ollama_base_url = if ollama_input == default_ollama {
        None // store None so the default takes effect
    } else if ollama_input.is_empty() {
        config.ollama_base_url.clone()
    } else {
        Some(ollama_input)
    };

    // Default model
    let current_model = config
        .default_model
        .as_deref()
        .unwrap_or("(provider default)");
    let model_input = prompt_plain("Default model override", current_model)?;
    config.default_model = if model_input.is_empty() || model_input == "(provider default)" {
        config.default_model.clone()
    } else if model_input == "clear" {
        None
    } else {
        Some(model_input)
    };

    // Default provider
    let provider_input = prompt_plain("Default provider", &config.default_provider)?;
    if !provider_input.is_empty() {
        config.default_provider = provider_input;
    }

    println!();
    config.save()?;
    println!("Config saved to {}", Config::config_path().display());

    // Validate and warn about keys
    let warnings = config.validate_keys();
    for w in &warnings {
        println!("  Warning: {}", w);
    }

    if warnings.is_empty() {
        println!("All API keys look valid.");
    }

    Ok(())
}

fn apply_flags(config: &mut Config, args: &SetupArgs) {
    if let Some(ref k) = args.anthropic_key {
        config.providers.anthropic_api_key = Some(k.clone());
    }
    if let Some(ref k) = args.openai_key {
        config.providers.openai_api_key = Some(k.clone());
    }
    if let Some(ref k) = args.google_key {
        config.providers.google_api_key = Some(k.clone());
    }
    if let Some(ref k) = args.openrouter_key {
        config.openrouter_api_key = Some(k.clone());
    }
    if let Some(ref u) = args.ollama_url {
        config.ollama_base_url = Some(u.clone());
    }
    if let Some(ref m) = args.default_model {
        config.default_model = Some(m.clone());
    }
}

/// Prompt for a secret value. Shows a redacted hint of the stored value.
/// Returns `None` if the user clears the value; preserves the existing value on empty input.
fn prompt_secret(
    label: &str,
    hint: &str,
    current: Option<&str>,
    display: Option<&str>,
) -> anyhow::Result<Option<String>> {
    let shown = display.unwrap_or("(not set)");
    print!("  {} [{}] ({}): ", label, shown, hint);
    io::stdout().flush()?;

    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let input = input.trim();

    Ok(if input == "clear" {
        None
    } else if input.is_empty() {
        current.map(|s| s.to_string())
    } else {
        Some(input.to_string())
    })
}

/// Prompt for a plain (non-secret) value.
fn prompt_plain(label: &str, current: &str) -> anyhow::Result<String> {
    print!("  {} [{}]: ", label, current);
    io::stdout().flush()?;

    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    Ok(input.trim().to_string())
}

/// Redact an API key for display: show first 8 chars + "...".
fn redact(key: &str) -> String {
    if key.len() <= 8 {
        "***".to_string()
    } else {
        format!("{}...", &key[..8])
    }
}

//! `lev test` - Run agent tests

use clap::Args;
use leviath_core::{Region, RegionKind};
use leviath_runtime::{AgentEngine, AgentPool, ProviderRegistry};
use serde::Deserialize;
use std::fs;
use std::path::Path;
use std::sync::Arc;

use super::run::parse_manifest_public;
use crate::config::Config;

#[derive(Args)]
pub struct TestArgs {
    /// Path to agent project
    #[arg(value_name = "PATH")]
    pub path: Option<String>,

    /// Test filter pattern
    #[arg(short, long)]
    pub filter: Option<String>,

    /// Validate test structure without running agents (no API calls)
    #[arg(long)]
    pub dry_run: bool,
}

/// A test case loaded from a TOML test file.
#[derive(Debug, Deserialize)]
#[allow(dead_code)]
struct TestCase {
    name: String,
    input: String,
    #[serde(default)]
    expect_contains: Option<String>,
    #[serde(default)]
    expect_tool_call: Option<String>,
    #[serde(default)]
    max_tokens: Option<usize>,
}

#[derive(Debug, Deserialize)]
struct TestFile {
    test: Vec<TestCase>,
}

pub async fn execute(args: TestArgs) -> anyhow::Result<()> {
    let path = args.path.unwrap_or_else(|| ".".to_string());
    tracing::info!(path = %path, "Running agent tests");

    let project_path = Path::new(&path);

    // Verify agent.leviath exists
    let manifest_path = project_path.join("agent.leviath");
    if !manifest_path.exists() {
        anyhow::bail!(
            "No agent.leviath found in '{}'. Not an agent project.",
            project_path.display()
        );
    }

    let tests_dir = project_path.join("tests");
    if !tests_dir.exists() {
        println!("No tests directory found. Create tests/ with .toml or .rhai files.");
        println!("\nExample test file (tests/basic.toml):");
        println!("  [[test]]");
        println!("  name = \"basic_response\"");
        println!("  input = \"Hello\"");
        println!("  expect_contains = \"hello\"");
        return Ok(());
    }

    if args.dry_run {
        println!("Dry run mode: validating test structure only (no API calls)\n");
    }

    // Parse blueprint and set up providers (only if not dry_run)
    let manifest_content = fs::read_to_string(&manifest_path)?;
    let blueprint = parse_manifest_public(&manifest_content)?;

    let registry = if !args.dry_run {
        let config = Config::load()?;
        let mut reg = ProviderRegistry::new();

        if let Some(ref key) = config.providers.anthropic_api_key {
            reg.register(
                "anthropic".to_string(),
                Arc::new(leviath_providers::AnthropicProvider::new(key.clone())),
            );
        }
        if let Some(ref key) = config.providers.openai_api_key {
            reg.register(
                "openai".to_string(),
                Arc::new(leviath_providers::OpenAIProvider::new(key.clone())),
            );
        }
        if let Some(ref key) = config.providers.google_api_key {
            reg.register(
                "google".to_string(),
                Arc::new(leviath_providers::GeminiProvider::new(key.clone())),
            );
        }
        if let Some(ref key) = config.openrouter_api_key {
            reg.register(
                "openrouter".to_string(),
                Arc::new(leviath_providers::OpenRouterProvider::new(key.clone())),
            );
        }
        let ollama_url = config
            .ollama_base_url
            .as_deref()
            .unwrap_or("http://localhost:11434");
        reg.register(
            "ollama".to_string(),
            Arc::new(leviath_providers::OllamaProvider::with_base_url(
                ollama_url.to_string(),
            )),
        );

        Some(reg)
    } else {
        None
    };

    let mut total = 0;
    let mut passed = 0;
    let mut failed = 0;
    let mut failures: Vec<String> = Vec::new();

    // Run .toml test files
    for entry in fs::read_dir(&tests_dir)? {
        let entry = entry?;
        let test_path = entry.path();

        if test_path.extension().and_then(|e| e.to_str()) == Some("toml") {
            let file_name = test_path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("unknown");

            println!("Running test file: {}", file_name);

            let content = fs::read_to_string(&test_path)?;
            let test_file: TestFile = toml::from_str(&content)
                .map_err(|e| anyhow::anyhow!("Failed to parse test file '{}': {}", file_name, e))?;

            for test_case in &test_file.test {
                // Apply filter if provided
                if let Some(ref filter) = args.filter {
                    if !test_case.name.contains(filter.as_str()) {
                        continue;
                    }
                }

                total += 1;

                if args.dry_run {
                    // Dry-run: validate structure only
                    let test_valid = validate_test_case(test_case);
                    if test_valid {
                        passed += 1;
                        println!("  PASS (dry-run): {}", test_case.name);
                    } else {
                        failed += 1;
                        let msg = format!("{}: test case validation failed", test_case.name);
                        println!("  FAIL (dry-run): {}", msg);
                        failures.push(msg);
                    }
                } else {
                    // Real run: execute inference and check assertions
                    let registry = registry
                        .as_ref()
                        .expect("registry should exist in non-dry-run");
                    match run_test_case(&blueprint, registry, test_case).await {
                        Ok(true) => {
                            passed += 1;
                            println!("  PASS: {}", test_case.name);
                        }
                        Ok(false) => {
                            failed += 1;
                            let msg = format!("{}: assertions failed", test_case.name);
                            println!("  FAIL: {}", msg);
                            failures.push(msg);
                        }
                        Err(e) => {
                            failed += 1;
                            let msg = format!("{}: {}", test_case.name, e);
                            println!("  FAIL: {}", msg);
                            failures.push(msg);
                        }
                    }
                }
            }
        }
    }

    // Run .rhai test scripts
    for entry in fs::read_dir(&tests_dir)? {
        let entry = entry?;
        let test_path = entry.path();

        if test_path.extension().and_then(|e| e.to_str()) == Some("rhai") {
            let file_name = test_path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("unknown");

            // Apply filter if provided
            if let Some(ref filter) = args.filter {
                if !file_name.contains(filter.as_str()) {
                    continue;
                }
            }

            total += 1;
            println!("Running script: {}", file_name);

            let script = fs::read_to_string(&test_path)?;
            let engine = leviath_scripting::ScriptEngine::new();
            let mut scope = rhai::Scope::new();

            match engine.execute(&script, &mut scope) {
                Ok(result) => {
                    if let Ok(success) = result.as_bool() {
                        if success {
                            passed += 1;
                            println!("  PASS: {}", file_name);
                        } else {
                            failed += 1;
                            let msg = format!("{}: script returned false", file_name);
                            println!("  FAIL: {}", msg);
                            failures.push(msg);
                        }
                    } else {
                        passed += 1;
                        println!("  PASS: {} (returned: {})", file_name, result);
                    }
                }
                Err(e) => {
                    failed += 1;
                    let msg = format!("{}: {}", file_name, e);
                    println!("  FAIL: {}", msg);
                    failures.push(msg);
                }
            }
        }
    }

    // Report results
    println!("\n--- Results ---");
    println!("{} passed, {} failed, {} total", passed, failed, total);

    if !failures.is_empty() {
        println!("\nFailures:");
        for f in &failures {
            println!("  - {}", f);
        }
        anyhow::bail!("{} test(s) failed", failed);
    }

    if total == 0 {
        println!("No test files found in tests/ directory.");
    }

    Ok(())
}

/// Run a single test case by spawning an agent and running one inference call.
async fn run_test_case(
    blueprint: &leviath_core::Blueprint,
    registry: &ProviderRegistry,
    test: &TestCase,
) -> anyhow::Result<bool> {
    // Create engine with providers
    let mut engine = AgentEngine::with_providers(registry.clone());

    // Create agent pool and spawn agent
    let mut pool = AgentPool::new(blueprint.clone());
    let agent_id = pool.spawn_agent(engine.world_mut());
    let entity = pool
        .get_agent(&agent_id)
        .ok_or_else(|| anyhow::anyhow!("Failed to get spawned agent entity"))?;

    // Initialize context window regions from blueprint layout
    if let Some(mut window) = engine
        .world_mut()
        .get_mut::<leviath_runtime::ContextWindow>(entity)
    {
        for region_def in &blueprint.context_layout.regions {
            let region = Region::new(
                region_def.name.clone(),
                region_def.kind.clone(),
                region_def.max_tokens,
            );
            window.add_region(region);
        }

        // Add tool_results region if not present
        if window.get_region("tool_results").is_none() {
            let tool_region = Region::new("tool_results".to_string(), RegionKind::Temporary, 5000);
            window.add_region(tool_region);
        }

        // Add test input to the first pinned/system region
        let system_region_name = blueprint
            .context_layout
            .regions
            .iter()
            .find(|r| matches!(r.kind, RegionKind::Pinned))
            .map(|r| r.name.clone());

        if let Some(region_name) = system_region_name {
            let task_tokens = test.input.len() / 4 + 1;
            let _ = window.add_to_region(&region_name, test.input.clone(), task_tokens);
        }
    }

    // Get model config from the first stage
    let stage = blueprint
        .stages
        .first()
        .ok_or_else(|| anyhow::anyhow!("Blueprint has no stages"))?;

    let provider_name = &stage.model.provider;
    let model_name = &stage.model.model;

    // Check if provider is available
    if !engine.providers().has(provider_name) {
        anyhow::bail!(
            "Provider '{}' is not configured. Set API key in ~/.leviath/config.toml",
            provider_name
        );
    }

    // Run a single inference call (not the full loop)
    let response = engine
        .run_inference(entity, provider_name, model_name, Vec::new())
        .await
        .map_err(|e| anyhow::anyhow!("Inference failed: {}", e))?;

    // Check assertions
    let mut all_passed = true;

    if let Some(ref expected) = test.expect_contains {
        let content_lower = response.content.to_lowercase();
        let expected_lower = expected.to_lowercase();
        if !content_lower.contains(&expected_lower) {
            println!(
                "    expect_contains failed: response does not contain '{}'",
                expected
            );
            println!("    response: {}", truncate_str(&response.content, 200));
            all_passed = false;
        }
    }

    if let Some(ref expected_tool) = test.expect_tool_call {
        let has_tool = response
            .tool_calls
            .iter()
            .any(|tc| tc.name == *expected_tool);
        if !has_tool {
            println!(
                "    expect_tool_call failed: no tool call to '{}'",
                expected_tool
            );
            let tool_names: Vec<&str> = response
                .tool_calls
                .iter()
                .map(|tc| tc.name.as_str())
                .collect();
            println!("    actual tool calls: {:?}", tool_names);
            all_passed = false;
        }
    }

    Ok(all_passed)
}

/// Validate a test case structure (checks that it's well-formed).
fn validate_test_case(test: &TestCase) -> bool {
    if test.name.is_empty() {
        return false;
    }
    if test.input.is_empty() {
        return false;
    }
    // Must have at least one assertion
    if test.expect_contains.is_none() && test.expect_tool_call.is_none() {
        return false;
    }
    true
}

fn truncate_str(s: &str, max: usize) -> String {
    if s.len() <= max {
        s.to_string()
    } else {
        format!("{}...", &s[..max])
    }
}

//! `lev validate` - Validate an agent blueprint.

use clap::Args;
use std::path::PathBuf;

#[derive(Args)]
pub struct ValidateArgs {
    /// Path to the agent directory or agent.leviath file
    #[arg(default_value = ".")]
    path: String,
}

pub async fn execute(args: ValidateArgs) -> anyhow::Result<()> {
    let path = PathBuf::from(&args.path);

    // Resolve manifest path
    let manifest_path = if path.is_file() {
        path.clone()
    } else {
        let p = path.join("agent.leviath");
        if !p.exists() {
            anyhow::bail!("No agent.leviath found at {}", path.display());
        }
        p
    };

    let content = std::fs::read_to_string(&manifest_path)
        .map_err(|e| anyhow::anyhow!("Failed to read {}: {}", manifest_path.display(), e))?;

    // Parse
    let blueprint = match super::run::parse_manifest_public(&content) {
        Ok(bp) => bp,
        Err(e) => {
            eprintln!("✗ Parse error: {}", e);
            std::process::exit(1);
        }
    };

    // Validate
    match blueprint.validate() {
        Ok(()) => {
            println!("✓ Blueprint '{}' is valid.", blueprint.name);
            println!(
                "  {} stages, version {}",
                blueprint.stages.len(),
                blueprint.version
            );

            // Check if graph mode
            let is_graph = blueprint.stages.iter().any(|s| s.transitions.is_some());
            if is_graph {
                let entry = blueprint.resolve_entry_stage_name();
                println!("  Graph mode: entry stage '{}'", entry);

                // List stages and their transitions
                for stage in &blueprint.stages {
                    let transitions_info = match &stage.transitions {
                        Some(t) if !t.is_empty() => {
                            let targets: Vec<&str> = t.keys().map(|k| k.as_str()).collect();
                            format!(" → {}", targets.join(", "))
                        }
                        Some(_) => " (terminal)".to_string(),
                        None => " (linear)".to_string(),
                    };
                    let revisits = stage
                        .max_revisits
                        .map(|n| format!(" (max_revisits: {})", n))
                        .unwrap_or_default();
                    println!("  - {}{}{}", stage.name, transitions_info, revisits);
                }
            } else {
                println!(
                    "  Linear mode: {}",
                    blueprint
                        .stages
                        .iter()
                        .map(|s| s.name.as_str())
                        .collect::<Vec<_>>()
                        .join(" → ")
                );
            }

            // Warnings (non-fatal)
            print_warnings(&blueprint);
        }
        Err(e) => {
            eprintln!("✗ Validation failed: {}", e);
            std::process::exit(1);
        }
    }

    Ok(())
}

fn print_warnings(blueprint: &leviath_core::Blueprint) {
    let stage_names: std::collections::HashSet<&str> =
        blueprint.stages.iter().map(|s| s.name.as_str()).collect();

    let is_graph = blueprint.stages.iter().any(|s| s.transitions.is_some());
    if !is_graph {
        return;
    }

    let entry = blueprint.resolve_entry_stage_name();

    // Check reachability via BFS from entry stage
    let mut reachable = std::collections::HashSet::new();
    let mut queue = std::collections::VecDeque::new();
    queue.push_back(entry.clone());
    while let Some(name) = queue.pop_front() {
        if !reachable.insert(name.clone()) {
            continue;
        }
        if let Some(stage) = blueprint.find_stage(&name) {
            if let Some(ref transitions) = stage.transitions {
                for target in transitions.keys() {
                    if !reachable.contains(target.as_str()) && stage_names.contains(target.as_str())
                    {
                        queue.push_back(target.clone());
                    }
                }
            }
        }
    }

    for stage in &blueprint.stages {
        if !reachable.contains(stage.name.as_str()) {
            println!(
                "  ⚠ Warning: stage '{}' is unreachable from entry stage '{}'",
                stage.name, entry
            );
        }
    }

    // Check for loops without max_revisits
    for stage in &blueprint.stages {
        if let Some(ref transitions) = stage.transitions {
            for target in transitions.keys() {
                if target != &stage.name {
                    // Check if target can reach back to this stage (cycle)
                    if let Some(target_stage) = blueprint.find_stage(target) {
                        if let Some(ref t2) = target_stage.transitions {
                            if t2.contains_key(&stage.name) && target_stage.max_revisits.is_none() {
                                println!(
                                    "  ⚠ Warning: stage '{}' is in a cycle but has no max_revisits set",
                                    target
                                );
                            }
                        }
                    }
                }
            }
        }
    }
}

