//! Leviath CLI - `lev` command-line interface.

use clap::{Parser, Subcommand};
use leviath_cli::commands;
use tracing::info;

/// Leviath CLI - Agent framework with structured context windows
#[derive(Parser)]
#[command(name = "lev")]
#[command(about = "Leviath agent framework CLI", long_about = None)]
#[command(version)]
struct Cli {
    /// Enable verbose logging
    #[arg(short, long, global = true)]
    verbose: bool,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Create a new agent blueprint
    Create(commands::create::CreateArgs),

    /// Configure API keys and defaults
    Setup(commands::setup::SetupArgs),

    /// Run an agent
    Run(commands::run::RunArgs),

    /// List available and installed blueprints
    List(commands::list::ListArgs),

    /// Install a blueprint
    Add(commands::add::AddArgs),

    /// Remove an installed blueprint
    Remove(commands::remove::RemoveArgs),

    /// Run blueprint tests
    Test(commands::test::TestArgs),

    /// Bundle a blueprint for distribution
    Pack(commands::pack::PackArgs),

    /// Interactive agent dashboard
    #[command(name = "dash")]
    Dashboard(commands::dashboard::DashboardArgs),

    /// List and inspect available models
    Models(commands::models::ModelsArgs),

    /// Validate an agent blueprint
    Validate(commands::validate::ValidateArgs),

    /// Start the REST + WebSocket API server
    Serve(commands::serve::ServeArgs),

    /// (Internal) Background worker process — do not call directly
    #[command(name = "__run-worker", hide = true)]
    RunWorker(commands::run::WorkerArgs),
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();

    // Initialize tracing
    let level = if cli.verbose { "debug" } else { "info" };
    tracing_subscriber::fmt().with_env_filter(level).init();

    info!("Leviath CLI v{}", env!("CARGO_PKG_VERSION"));

    // Dispatch commands
    match cli.command {
        Commands::Create(args) => commands::create::execute(args).await,
        Commands::Setup(args) => commands::setup::execute(args).await,
        Commands::Run(args) => commands::run::execute(args).await,
        Commands::List(args) => commands::list::execute(args).await,
        Commands::Add(args) => commands::add::execute(args).await,
        Commands::Remove(args) => commands::remove::execute(args).await,
        Commands::Test(args) => commands::test::execute(args).await,
        Commands::Pack(args) => commands::pack::execute(args).await,
        Commands::Dashboard(args) => commands::dashboard::execute(args).await,
        Commands::Models(args) => commands::models::execute(args).await,
        Commands::Validate(args) => commands::validate::execute(args).await,
        Commands::Serve(args) => commands::serve::execute(args).await,
        Commands::RunWorker(args) => commands::run::execute_worker(args).await,
    }
}

//! Markdown → ratatui `Text` renderer.
//!
//! Converts a markdown string to a `ratatui::text::Text<'static>` using
//! `pulldown-cmark`.  Designed for rendering agent output inside the dashboard's
//! content panes where only `Paragraph` + `Text` are available (no nested widgets).
//!
//! Feature coverage:
//! - Headings H1–H6 (bold + accent colour, H1 gets an underline rule)
//! - Paragraphs with soft/hard breaks
//! - Bullet and ordered lists (nested up to depth 3)
//! - Blockquotes (dim, "│ " prefix)
//! - Inline `code`, **bold**, *italic*, ~~strikethrough~~, links (underlined)
//! - Fenced code blocks (tinted, language tag in title line)
//! - `mermaid` fenced blocks → styled fallback box with a hint to install mmdc
//! - Horizontal rules (dim dashes)
//!
//! Plain text that contains no markdown degrades cleanly — it just renders as
//! white text.

use pulldown_cmark::{CodeBlockKind, Event, HeadingLevel, Options, Parser, Tag, TagEnd};
use ratatui::{
    style::{Color, Modifier, Style},
    text::{Line, Span, Text},
};

// ─── Palette (mirrors the dashboard theme) ────────────────────────────────────

const C_ACCENT: Color = Color::Cyan;
const C_SUCCESS: Color = Color::Green;
const C_DIM: Color = Color::DarkGray;
const C_MUTED: Color = Color::Gray;
const C_WHITE: Color = Color::White;
const C_CODE_BG: Color = Color::Rgb(30, 30, 40);

// ─── Public API ───────────────────────────────────────────────────────────────

/// Convert a markdown string to ratatui `Text` for rendering in a `Paragraph`.
///
/// `width` is used to draw horizontal rules to the correct width.
pub fn markdown_to_text(input: &str, width: u16) -> Text<'static> {
    let mut renderer = Renderer::new(width);
    renderer.render(input);
    Text::from(renderer.lines)
}

// ─── Renderer internals ───────────────────────────────────────────────────────

/// Stack of style modifiers accumulated from nested inline tags.
#[derive(Default, Clone)]
struct InlineStyle {
    bold: bool,
    italic: bool,
    strikethrough: bool,
    code: bool,
    link: bool,
}

impl InlineStyle {
    fn to_ratatui_style(&self) -> Style {
        let mut style = Style::default().fg(C_WHITE);
        if self.code {
            style = style.fg(Color::Rgb(200, 160, 100)).bg(C_CODE_BG);
        } else if self.link {
            style = style.fg(C_ACCENT).add_modifier(Modifier::UNDERLINED);
        }
        if self.bold {
            style = style.add_modifier(Modifier::BOLD);
        }
        if self.italic {
            style = style.add_modifier(Modifier::ITALIC);
        }
        if self.strikethrough {
            style = style.add_modifier(Modifier::CROSSED_OUT);
        }
        style
    }
}

struct Renderer {
    lines: Vec<Line<'static>>,
    /// Spans being accumulated for the current line.
    current_spans: Vec<Span<'static>>,
    /// Inline style stack (push/pop for nested inline tags).
    inline_stack: Vec<InlineStyle>,
    /// Current inline style (derived from the stack).
    inline: InlineStyle,
    /// Whether we're currently inside a fenced code block.
    in_code_block: bool,
    /// Language hint for the current code block.
    code_lang: Option<String>,
    /// Source lines accumulated within a code block.
    code_lines: Vec<String>,
    /// List nesting stack: None = bullet, Some(n) = ordered (current item #).
    list_stack: Vec<Option<u64>>,
    /// Terminal width (used for HR lines).
    width: u16,
}

impl Renderer {
    fn new(width: u16) -> Self {
        Self {
            lines: Vec::new(),
            current_spans: Vec::new(),
            inline_stack: Vec::new(),
            inline: InlineStyle::default(),
            in_code_block: false,
            code_lang: None,
            code_lines: Vec::new(),
            list_stack: Vec::new(),
            width,
        }
    }

    /// Flush `current_spans` into a finished `Line`.
    fn flush_line(&mut self) {
        let spans = std::mem::take(&mut self.current_spans);
        self.lines.push(Line::from(spans));
    }

    /// Push a fully-built `Line` directly.
    fn push_line(&mut self, line: Line<'static>) {
        if !self.current_spans.is_empty() {
            self.flush_line();
        }
        self.lines.push(line);
    }

    /// Push an empty blank line.
    fn blank_line(&mut self) {
        self.push_line(Line::from(""));
    }

    /// Current list indent (2 spaces per nesting level).
    fn list_indent(&self) -> String {
        "  ".repeat(self.list_stack.len())
    }

    /// Rebuild the active inline style from the stack top.
    fn sync_inline(&mut self) {
        self.inline = self.inline_stack.last().cloned().unwrap_or_default();
    }

    fn push_inline(&mut self, mut new_style: InlineStyle) {
        // Inherit accumulated modifiers from parent
        if let Some(parent) = self.inline_stack.last() {
            if parent.bold {
                new_style.bold = true;
            }
            if parent.italic {
                new_style.italic = true;
            }
            if parent.strikethrough {
                new_style.strikethrough = true;
            }
        }
        self.inline_stack.push(new_style);
        self.sync_inline();
    }

    fn pop_inline(&mut self) {
        self.inline_stack.pop();
        self.sync_inline();
    }

    /// Emit a span of text with the current inline style.
    fn emit_text(&mut self, text: &str) {
        let style = self.inline.to_ratatui_style();
        // Preserve leading space so words don't jam together
        self.current_spans
            .push(Span::styled(text.to_owned(), style));
    }

    /// Render a complete code block (fenced or mermaid).
    fn flush_code_block(&mut self) {
        let lang = self.code_lang.take().unwrap_or_default();
        let content = std::mem::take(&mut self.code_lines);
        let is_mermaid = lang.trim().to_lowercase() == "mermaid";

        if is_mermaid {
            // ── Mermaid fallback ─────────────────────────────────────────────
            self.push_line(Line::from(vec![
                Span::styled(
                    "  ◇ ",
                    Style::default().fg(C_ACCENT).add_modifier(Modifier::BOLD),
                ),
                Span::styled("mermaid diagram", Style::default().fg(C_ACCENT)),
                Span::styled(" — source", Style::default().fg(C_DIM)),
            ]));
            for code_line in &content {
                self.push_line(Line::from(vec![
                    Span::styled("  │ ", Style::default().fg(C_DIM)),
                    Span::styled(code_line.to_owned(), Style::default().fg(C_MUTED)),
                ]));
            }
            self.push_line(Line::from(Span::styled(
                "  ↑ Install mermaid-cli (mmdc) to render as a diagram",
                Style::default().fg(C_DIM),
            )));
        } else {
            // ── Regular code block ───────────────────────────────────────────
            let lang_label = if lang.is_empty() {
                "code".to_string()
            } else {
                lang.clone()
            };
            self.push_line(Line::from(vec![
                Span::styled("  ╭─ ", Style::default().fg(C_DIM)),
                Span::styled(
                    lang_label,
                    Style::default().fg(C_MUTED).add_modifier(Modifier::BOLD),
                ),
                Span::styled(" ─", Style::default().fg(C_DIM)),
            ]));
            for code_line in &content {
                self.push_line(Line::from(vec![
                    Span::styled("  │ ", Style::default().fg(C_DIM)),
                    Span::styled(
                        code_line.to_owned(),
                        Style::default().fg(Color::Rgb(200, 200, 140)).bg(C_CODE_BG),
                    ),
                ]));
            }
            self.push_line(Line::from(Span::styled("  ╰─", Style::default().fg(C_DIM))));
        }
        self.in_code_block = false;
    }

    pub fn render(&mut self, input: &str) {
        let opts = Options::ENABLE_STRIKETHROUGH | Options::ENABLE_TABLES;
        let parser = Parser::new_ext(input, opts);

        for event in parser {
            match event {
                // ── Block starts ─────────────────────────────────────────────
                Event::Start(Tag::Heading { level, .. }) => {
                    // Flush any pending content and start a fresh heading line
                    if !self.current_spans.is_empty() {
                        self.flush_line();
                    }
                    // Blank line before non-first headings
                    if !self.lines.is_empty() {
                        self.blank_line();
                    }
                    // Visual decorators — convey depth without # text (terminal can't vary font size)
                    let (color, prefix, bold) = match level {
                        HeadingLevel::H1 => (C_ACCENT, "▌ ", true),
                        HeadingLevel::H2 => (C_ACCENT, "▎ ", true),
                        HeadingLevel::H3 => (C_SUCCESS, "  ", true),
                        HeadingLevel::H4 => (C_MUTED, "   ", false),
                        HeadingLevel::H5 => (C_DIM, "    ", false),
                        HeadingLevel::H6 => (C_DIM, "     ", false),
                    };
                    let mut sty = Style::default().fg(color);
                    if bold {
                        sty = sty.add_modifier(Modifier::BOLD);
                    }
                    self.current_spans.push(Span::styled(prefix, sty));
                    self.push_inline(InlineStyle {
                        bold,
                        ..Default::default()
                    });
                }
                Event::End(TagEnd::Heading(level)) => {
                    self.pop_inline();
                    self.flush_line();
                    // H1 gets a dim underline rule
                    if level == HeadingLevel::H1 {
                        let rule_w = (self.width as usize).saturating_sub(2).max(8);
                        self.push_line(Line::from(Span::styled(
                            "─".repeat(rule_w),
                            Style::default().fg(C_DIM),
                        )));
                    }
                    self.blank_line();
                }

                Event::Start(Tag::Paragraph) => {}
                Event::End(TagEnd::Paragraph) => {
                    self.flush_line();
                    self.blank_line();
                }

                Event::Start(Tag::BlockQuote(_)) => {
                    self.push_inline(InlineStyle {
                        ..Default::default()
                    });
                    self.current_spans
                        .push(Span::styled("│ ", Style::default().fg(C_DIM)));
                }
                Event::End(TagEnd::BlockQuote(_)) => {
                    self.pop_inline();
                    if !self.current_spans.is_empty() {
                        self.flush_line();
                    }
                    self.blank_line();
                }

                Event::Start(Tag::List(start)) => {
                    self.list_stack.push(start);
                }
                Event::End(TagEnd::List(_)) => {
                    self.list_stack.pop();
                    if self.list_stack.is_empty() {
                        self.blank_line();
                    }
                }
                Event::Start(Tag::Item) => {
                    if !self.current_spans.is_empty() {
                        self.flush_line();
                    }
                    let indent = self.list_indent();
                    let bullet = match self.list_stack.last() {
                        Some(None) => "● ".to_string(),
                        Some(Some(n)) => format!("{}. ", n),
                        None => "● ".to_string(),
                    };
                    // Increment ordered list counter
                    if let Some(Some(ref mut n)) = self.list_stack.last_mut() {
                        *n += 1;
                    }
                    self.current_spans.push(Span::styled(
                        format!("{}{}", indent, bullet),
                        Style::default().fg(C_ACCENT),
                    ));
                }
                Event::End(TagEnd::Item) => {
                    if !self.current_spans.is_empty() {
                        self.flush_line();
                    }
                }

                Event::Start(Tag::CodeBlock(kind)) => {
                    self.in_code_block = true;
                    self.code_lang = match kind {
                        CodeBlockKind::Fenced(lang) => {
                            let s = lang.into_string();
                            if s.is_empty() {
                                None
                            } else {
                                Some(s)
                            }
                        }
                        CodeBlockKind::Indented => None,
                    };
                    self.code_lines = Vec::new();
                    if !self.current_spans.is_empty() {
                        self.flush_line();
                    }
                }
                Event::End(TagEnd::CodeBlock) => {
                    self.flush_code_block();
                }

                Event::Start(Tag::Strong) => {
                    self.push_inline(InlineStyle {
                        bold: true,
                        ..Default::default()
                    });
                }
                Event::End(TagEnd::Strong) => {
                    self.pop_inline();
                }

                Event::Start(Tag::Emphasis) => {
                    self.push_inline(InlineStyle {
                        italic: true,
                        ..Default::default()
                    });
                }
                Event::End(TagEnd::Emphasis) => {
                    self.pop_inline();
                }

                Event::Start(Tag::Strikethrough) => {
                    self.push_inline(InlineStyle {
                        strikethrough: true,
                        ..Default::default()
                    });
                }
                Event::End(TagEnd::Strikethrough) => {
                    self.pop_inline();
                }

                Event::Start(Tag::Link { dest_url, .. }) => {
                    self.push_inline(InlineStyle {
                        link: true,
                        ..Default::default()
                    });
                    // Show the URL as a dim suffix after the link text
                    let url = dest_url.into_string();
                    if !url.is_empty() {
                        // We'll append the URL after the link text in End(Link)
                        // Store it via a span now so we can reference it; simpler: just push
                        // a placeholder and let the text events fill in link text.
                        // We push the URL as a trailing span at End(Link).
                        // Use a little indirection: push the open bracket.
                        self.current_spans
                            .push(Span::styled("[", Style::default().fg(C_DIM)));
                        // Stash URL in a "pending link url" field would be ideal.
                        // For simplicity, store it as a special span at end.
                        // We'll capture the URL by pushing it immediately at End.
                        // So skip storing; just remember we need to close.
                        let _ = url; // url emitted at End(Link) via stored span approach
                    }
                }
                Event::End(TagEnd::Link) => {
                    self.pop_inline();
                    self.current_spans
                        .push(Span::styled("]", Style::default().fg(C_DIM)));
                }

                // ── Inline events ────────────────────────────────────────────
                Event::Text(text) => {
                    if self.in_code_block {
                        // Accumulate raw code lines
                        for line in text.lines() {
                            self.code_lines.push(line.to_string());
                        }
                    } else {
                        let t = text.into_string();
                        if t.contains('\n') {
                            let mut first = true;
                            for part in t.split('\n') {
                                if !first {
                                    self.flush_line();
                                }
                                first = false;
                                if !part.is_empty() {
                                    self.emit_text(part);
                                }
                            }
                        } else {
                            self.emit_text(&t);
                        }
                    }
                }

                Event::Code(text) => {
                    // Inline code span
                    self.current_spans.push(Span::styled(
                        text.into_string(),
                        Style::default().fg(Color::Rgb(200, 160, 100)).bg(C_CODE_BG),
                    ));
                }

                Event::SoftBreak => {
                    // Soft breaks just become a space in terminal output
                    self.current_spans.push(Span::raw(" "));
                }
                Event::HardBreak => {
                    self.flush_line();
                }

                Event::Rule => {
                    if !self.current_spans.is_empty() {
                        self.flush_line();
                    }
                    let w = (self.width as usize).saturating_sub(2).max(8);
                    self.push_line(Line::from(Span::styled(
                        "─".repeat(w),
                        Style::default().fg(C_DIM),
                    )));
                    self.blank_line();
                }

                // Ignore HTML, footnotes, task list markers, math, etc.
                _ => {}
            }
        }

        // Flush any trailing content
        if !self.current_spans.is_empty() {
            self.flush_line();
        }
    }
}

// ─── Tests ────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn plain_text_renders_as_single_line() {
        let text = markdown_to_text("Hello, world!", 80);
        assert!(!text.lines.is_empty());
        // The content should contain our text somewhere
        let all: String = text
            .lines
            .iter()
            .flat_map(|l| l.spans.iter().map(|s| s.content.as_ref()))
            .collect();
        assert!(all.contains("Hello, world!"), "got: {}", all);
    }

    #[test]
    fn heading_produces_lines() {
        let text = markdown_to_text("# My Heading\n\nSome paragraph.", 80);
        let all: String = text
            .lines
            .iter()
            .flat_map(|l| l.spans.iter().map(|s| s.content.as_ref()))
            .collect::<String>();
        assert!(all.contains("My Heading"), "got: {}", all);
        assert!(all.contains("Some paragraph"), "got: {}", all);
    }

    #[test]
    fn code_block_renders_with_border() {
        let md = "```rust\nfn main() {}\n```";
        let text = markdown_to_text(md, 80);
        let all: String = text
            .lines
            .iter()
            .flat_map(|l| l.spans.iter().map(|s| s.content.as_ref()))
            .collect::<String>();
        assert!(all.contains("fn main() {}"), "got: {}", all);
        // Should have a border glyph
        assert!(
            all.contains("╭") || all.contains("│"),
            "no border found in: {}",
            all
        );
    }

    #[test]
    fn mermaid_block_shows_hint() {
        let md = "```mermaid\ngraph LR\n  A --> B\n```";
        let text = markdown_to_text(md, 80);
        let all: String = text
            .lines
            .iter()
            .flat_map(|l| l.spans.iter().map(|s| s.content.as_ref()))
            .collect::<String>();
        assert!(all.contains("mermaid"), "got: {}", all);
        assert!(
            all.contains("mmdc") || all.contains("Install"),
            "got: {}",
            all
        );
    }

    #[test]
    fn list_renders_bullets() {
        let md = "- item one\n- item two";
        let text = markdown_to_text(md, 80);
        let all: String = text
            .lines
            .iter()
            .flat_map(|l| l.spans.iter().map(|s| s.content.as_ref()))
            .collect::<String>();
        assert!(all.contains("item one"), "got: {}", all);
        assert!(all.contains("item two"), "got: {}", all);
    }
}

//! On-disk run state for background agent executions.
//!
//! Each run lives under ~/.leviath/runs/<run-id>/ with:
//! - `meta.json`    — run metadata, updated atomically (tmp + rename)
//! - `output.log`  — append-only combined worker stdout (legacy/fallback)
//! - `stages.json` — index of per-stage records
//! - `stages/<idx>/output.log` — readable agent output for that stage
//! - `stages/<idx>/logs.log`   — operational events + tool activity
//! - `stages/<idx>/context.json` — context snapshot for that stage
//!
//! The dashboard's activity log is persisted separately at:
//! - `~/.leviath/dashboard.log` — never cleared, appended across sessions

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};

/// Current status of a background run.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum RunStatus {
    Starting,
    Running,
    WaitingInput,
    Complete,
    /// All required stages done; agent still accepts optional follow-up input.
    /// Shown as "Complete" in the dashboard — no kill option, input still enabled.
    CompleteInteractive,
    Error,
    Cancelled,
}

impl std::fmt::Display for RunStatus {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            RunStatus::Starting => write!(f, "Starting"),
            RunStatus::Running => write!(f, "Running"),
            RunStatus::WaitingInput => write!(f, "WaitingInput"),
            RunStatus::Complete => write!(f, "Complete"),
            RunStatus::CompleteInteractive => write!(f, "CompleteInteractive"),
            RunStatus::Error => write!(f, "Error"),
            RunStatus::Cancelled => write!(f, "Cancelled"),
        }
    }
}

/// Metadata for a single background agent run.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RunMeta {
    pub run_id: String,
    pub agent_name: String,
    /// Absolute path to the agent manifest directory
    pub agent_path: String,
    pub task: String,
    pub model: Option<String>,
    /// PID of the worker process
    pub pid: u32,
    pub status: RunStatus,
    pub current_stage: String,
    pub stage_index: usize,
    pub num_stages: usize,
    pub iteration: usize,
    pub prompt_tokens: usize,
    pub completion_tokens: usize,
    /// Cumulative tokens read from provider cache.
    #[serde(default)]
    pub cached_tokens: usize,
    /// Absolute path to the working directory for tool execution
    pub workdir: String,
    /// Unix timestamp (seconds)
    pub started_at: i64,
    /// Unix timestamp (seconds)
    pub updated_at: i64,
    pub error: Option<String>,
    /// Short human-readable title generated from the task prompt (None until generated).
    #[serde(default)]
    pub title: Option<String>,
    /// Custom key-value pairs from the spawn request (API metadata).
    #[serde(default)]
    pub metadata: HashMap<String, String>,
    /// Webhook URL to POST on agent completion/error.
    #[serde(default)]
    pub callback_url: Option<String>,
    /// Links sub-agent runs to their parent run.
    #[serde(default)]
    pub parent_run_id: Option<String>,
}

impl RunMeta {
    pub fn new(
        run_id: String,
        agent_name: String,
        agent_path: String,
        task: String,
        model: Option<String>,
        workdir: String,
        num_stages: usize,
    ) -> Self {
        let now = now_secs();
        Self {
            run_id,
            agent_name,
            agent_path,
            task,
            model,
            pid: 0,
            status: RunStatus::Starting,
            current_stage: String::new(),
            stage_index: 0,
            num_stages,
            iteration: 0,
            prompt_tokens: 0,
            completion_tokens: 0,
            cached_tokens: 0,
            workdir,
            started_at: now,
            updated_at: now,
            error: None,
            title: None,
            metadata: HashMap::new(),
            callback_url: None,
            parent_run_id: None,
        }
    }

    pub fn touch(&mut self) {
        self.updated_at = now_secs();
    }
}

/// One content entry within a region, captured at snapshot time.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RegionEntrySnapshot {
    pub content: String,
    pub tokens: usize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub metadata: Option<serde_json::Value>,
}

/// Per-region token snapshot written by the background worker after each inference.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RegionSnapshot {
    pub name: String,
    /// Stringified kind: "pinned", "temporary", "clearable", "sliding", "compacting", "history"
    pub kind: String,
    pub current_tokens: usize,
    pub max_tokens: usize,
    /// Actual content entries stored in this region (empty for zero-token regions).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub entries: Vec<RegionEntrySnapshot>,
}

/// Snapshot of the full context window, written to `context.json` alongside `meta.json`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContextSnapshot {
    pub stage_name: String,
    pub total_tokens: usize,
    pub max_tokens: usize,
    pub regions: Vec<RegionSnapshot>,
}

/// Atomically write a context snapshot for the run.
pub fn write_context_snapshot(run_id: &str, snap: &ContextSnapshot) -> anyhow::Result<()> {
    let path = run_dir(run_id).join("context.json");
    let tmp = path.with_extension("json.tmp");
    let json = serde_json::to_string_pretty(snap)?;
    std::fs::write(&tmp, &json)?;
    std::fs::rename(&tmp, &path)?;
    Ok(())
}

/// Read the context snapshot for a run, if present.
pub fn read_context_snapshot(run_id: &str) -> Option<ContextSnapshot> {
    let path = run_dir(run_id).join("context.json");
    let json = std::fs::read_to_string(&path).ok()?;
    serde_json::from_str(&json).ok()
}

fn now_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

/// Directory where all run state is stored.
pub fn runs_dir() -> PathBuf {
    dirs::home_dir()
        .unwrap_or_default()
        .join(".leviath")
        .join("runs")
}

/// Directory for a specific run.
pub fn run_dir(run_id: &str) -> PathBuf {
    runs_dir().join(run_id)
}

/// Path to the persistent dashboard activity log (~/.leviath/dashboard.log).
pub fn dashboard_log_path() -> PathBuf {
    dirs::home_dir()
        .unwrap_or_default()
        .join(".leviath")
        .join("dashboard.log")
}

/// Append a timestamped line to the persistent dashboard activity log.
/// Silently ignores I/O errors — the dashboard log is best-effort.
pub fn append_dashboard_log(msg: &str) {
    use std::io::Write;
    let path = dashboard_log_path();
    // Ensure the parent directory exists (first-run case).
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    if let Ok(mut file) = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
    {
        let timestamp = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
        let _ = writeln!(file, "{} {}", timestamp, msg);
    }
}

/// Generate a unique run ID: "<agent_name>-<timestamp>-<suffix>".
pub fn new_run_id(agent_name: &str) -> String {
    let now = now_secs();
    // 4-char pseudo-random suffix from the lower bits of a stack address
    let suffix = format!("{:04x}", (now & 0xffff) ^ (now >> 16 & 0xffff));
    let safe_name = agent_name.replace(|c: char| !c.is_alphanumeric() && c != '-', "-");
    format!("{}-{}-{}", safe_name, now, suffix)
}

/// Create the run directory and write initial metadata.
pub fn create_run(meta: &RunMeta) -> anyhow::Result<()> {
    let dir = run_dir(&meta.run_id);
    std::fs::create_dir_all(&dir)?;

    // Set restrictive permissions on the run directory (Unix only)
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let perms = std::fs::Permissions::from_mode(0o700);
        let _ = std::fs::set_permissions(&dir, perms);
    }

    write_meta(meta)
}

/// Atomically write run metadata (write to tmp, then rename).
pub fn write_meta(meta: &RunMeta) -> anyhow::Result<()> {
    let dir = run_dir(&meta.run_id);
    let tmp_path = dir.join("meta.json.tmp");
    let final_path = dir.join("meta.json");

    let json = serde_json::to_string_pretty(meta)?;
    std::fs::write(&tmp_path, &json)?;
    std::fs::rename(&tmp_path, &final_path)?;

    Ok(())
}

/// Read run metadata for a given run ID.
pub fn read_meta(run_id: &str) -> anyhow::Result<RunMeta> {
    let path = run_dir(run_id).join("meta.json");
    let json = std::fs::read_to_string(&path)?;
    Ok(serde_json::from_str(&json)?)
}

/// List all runs, sorted by started_at descending (most recent first).
/// Silently skips any runs whose metadata cannot be read.
pub fn list_runs() -> Vec<RunMeta> {
    let dir = runs_dir();
    if !dir.exists() {
        return Vec::new();
    }

    let mut runs = Vec::new();

    if let Ok(entries) = std::fs::read_dir(&dir) {
        for entry in entries.filter_map(|e| e.ok()) {
            let run_id = entry.file_name().to_string_lossy().to_string();
            if let Ok(meta) = read_meta(&run_id) {
                runs.push(meta);
            }
        }
    }

    runs.sort_by_key(|r| std::cmp::Reverse(r.started_at));
    runs
}

/// Read the last `max_bytes` of any file on disk, returning UTF-8 text.
/// If the file is smaller than `max_bytes` the whole file is returned.
/// Partial UTF-8 at the truncation boundary is handled by skipping to the
/// first newline.  Returns an empty string on any I/O error.
pub fn tail_file(path: &std::path::Path, max_bytes: u64) -> String {
    if !path.exists() {
        return String::new();
    }

    let metadata = match std::fs::metadata(path) {
        Ok(m) => m,
        Err(_) => return String::new(),
    };

    let file_size = metadata.len();
    if file_size <= max_bytes {
        return std::fs::read_to_string(path).unwrap_or_default();
    }

    use std::io::{Read, Seek, SeekFrom};
    let mut file = match std::fs::File::open(path) {
        Ok(f) => f,
        Err(_) => return String::new(),
    };

    let offset = file_size - max_bytes;
    if file.seek(SeekFrom::Start(offset)).is_err() {
        return String::new();
    }

    let mut buf = Vec::new();
    let _ = file.read_to_end(&mut buf);

    // Skip to the first newline so we don't emit a partial line at the start.
    if let Some(nl) = buf.iter().position(|&b| b == b'\n') {
        String::from_utf8_lossy(&buf[nl + 1..]).to_string()
    } else {
        String::from_utf8_lossy(&buf).to_string()
    }
}

/// Read the last `max_bytes` of a run's combined output log (legacy).
#[allow(dead_code)]
pub fn tail_log(run_id: &str, max_bytes: u64) -> String {
    tail_file(&run_dir(run_id).join("output.log"), max_bytes)
}

// ─── Per-stage persistence ────────────────────────────────────────────────────

/// Status of an individual stage within a run.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum StageRunStatus {
    Pending,
    Active,
    WaitingInput,
    Complete,
    Error,
}

impl std::fmt::Display for StageRunStatus {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            StageRunStatus::Pending => write!(f, "Pending"),
            StageRunStatus::Active => write!(f, "Active"),
            StageRunStatus::WaitingInput => write!(f, "WaitingInput"),
            StageRunStatus::Complete => write!(f, "Complete"),
            StageRunStatus::Error => write!(f, "Error"),
        }
    }
}

/// Metadata record for a single stage within a run.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StageRecord {
    pub name: String,
    pub index: usize,
    pub status: StageRunStatus,
    pub prompt_tokens: usize,
    pub completion_tokens: usize,
    /// Tokens read from provider cache in this stage.
    #[serde(default)]
    pub cached_tokens: usize,
    /// Unix timestamp (seconds); None until the stage starts.
    pub started_at: Option<i64>,
    /// Unix timestamp (seconds); None until the stage ends.
    pub ended_at: Option<i64>,
}

impl StageRecord {
    pub fn new(name: String, index: usize) -> Self {
        Self {
            name,
            index,
            status: StageRunStatus::Pending,
            prompt_tokens: 0,
            completion_tokens: 0,
            cached_tokens: 0,
            started_at: None,
            ended_at: None,
        }
    }
}

/// Directory for per-stage files within a run.
pub fn stage_dir(run_id: &str, stage_idx: usize) -> PathBuf {
    run_dir(run_id).join("stages").join(stage_idx.to_string())
}

/// Atomically write the stages index for a run.
pub fn write_stages_index(run_id: &str, stages: &[StageRecord]) -> anyhow::Result<()> {
    let path = run_dir(run_id).join("stages.json");
    let tmp = path.with_extension("json.tmp");
    let json = serde_json::to_string_pretty(stages)?;
    std::fs::write(&tmp, &json)?;
    std::fs::rename(&tmp, &path)?;
    Ok(())
}

/// Read the stages index for a run, or return an empty vec on any error.
pub fn read_stages_index(run_id: &str) -> Vec<StageRecord> {
    let path = run_dir(run_id).join("stages.json");
    let json = match std::fs::read_to_string(&path) {
        Ok(j) => j,
        Err(_) => return Vec::new(),
    };
    serde_json::from_str(&json).unwrap_or_default()
}

/// Ensure the per-stage directory exists (called before first write).
fn ensure_stage_dir(run_id: &str, stage_idx: usize) {
    let dir = stage_dir(run_id, stage_idx);
    let _ = std::fs::create_dir_all(&dir);
}

/// Append a line of readable agent output to the per-stage output log.
pub fn append_stage_output(run_id: &str, stage_idx: usize, text: &str) {
    use std::io::Write;
    ensure_stage_dir(run_id, stage_idx);
    let path = stage_dir(run_id, stage_idx).join("output.log");
    if let Ok(mut file) = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
    {
        let _ = writeln!(file, "{}", text);
    }
}

/// Append a line of operational/tool-activity log to the per-stage logs file.
pub fn append_stage_log(run_id: &str, stage_idx: usize, text: &str) {
    use std::io::Write;
    ensure_stage_dir(run_id, stage_idx);
    let path = stage_dir(run_id, stage_idx).join("logs.log");
    if let Ok(mut file) = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
    {
        let _ = writeln!(file, "{}", text);
    }
}

/// Atomically write a context snapshot for a specific stage.
pub fn write_stage_context(
    run_id: &str,
    stage_idx: usize,
    snap: &ContextSnapshot,
) -> anyhow::Result<()> {
    ensure_stage_dir(run_id, stage_idx);
    let path = stage_dir(run_id, stage_idx).join("context.json");
    let tmp = path.with_extension("json.tmp");
    let json = serde_json::to_string_pretty(snap)?;
    std::fs::write(&tmp, &json)?;
    std::fs::rename(&tmp, &path)?;
    Ok(())
}

/// Read the context snapshot for a specific stage, if present.
pub fn read_stage_context(run_id: &str, stage_idx: usize) -> Option<ContextSnapshot> {
    let path = stage_dir(run_id, stage_idx).join("context.json");
    let json = std::fs::read_to_string(&path).ok()?;
    serde_json::from_str(&json).ok()
}

/// Read the last `max_bytes` of the readable output log for a specific stage.
pub fn tail_stage_output(run_id: &str, stage_idx: usize, max_bytes: u64) -> String {
    tail_file(&stage_dir(run_id, stage_idx).join("output.log"), max_bytes)
}

/// Read the last `max_bytes` of the operational log for a specific stage.
pub fn tail_stage_log(run_id: &str, stage_idx: usize, max_bytes: u64) -> String {
    tail_file(&stage_dir(run_id, stage_idx).join("logs.log"), max_bytes)
}

