//! Unified tool registry combining built-in tools and MCP-discovered tools.

use std::collections::{HashMap, HashSet};
use std::path::PathBuf;
use std::sync::Arc;
use tokio::sync::Mutex;

use leviath_mcp::{ToolDiscovery, ToolExecutor};
use leviath_providers::Tool;
use leviath_tools::{BuiltinTools, ToolContext};

use crate::config::{Config, ToolPolicy};

/// Combined tool registry: native built-in tools + MCP-discovered tools.
///
/// Cheap to clone (all fields are `Arc`s). The `call` method dispatches
/// to the appropriate executor.
pub struct ToolRegistry {
    pub builtins: Arc<BuiltinTools>,
    pub mcp: Arc<Mutex<ToolExecutor>>,
    pub mcp_tool_defs: Vec<Tool>,
    pub builtin_names: HashSet<String>,
    #[allow(dead_code)]
    pub subagent_names: HashSet<String>,
}

impl ToolRegistry {
    /// Build a registry, connecting MCP servers declared in config (non-fatal).
    pub async fn build(workdir: PathBuf, config: &Config) -> Self {
        let ctx = ToolContext::new(workdir);
        let builtins = Arc::new(BuiltinTools::new(ctx));
        let builtin_names: HashSet<String> = builtins.names().into_iter().collect();

        let mut mcp_executor = ToolExecutor::new();
        let mut mcp_tool_defs = Vec::new();

        if !config.mcp_servers.is_empty() {
            let mut discovery = ToolDiscovery::new();
            for server_cfg in &config.mcp_servers {
                match discovery.discover_from_config(server_cfg).await {
                    Ok((tool_metas, client)) => {
                        mcp_executor.add_client(server_cfg.name.clone(), client);
                        for meta in tool_metas {
                            mcp_tool_defs.push(Tool {
                                name: meta.name,
                                description: meta.description,
                                parameters: meta.schema,
                            });
                        }
                        tracing::info!(server = %server_cfg.name, "Connected MCP server");
                    }
                    Err(e) => {
                        tracing::warn!(
                            server = %server_cfg.name,
                            error = %e,
                            "Failed to connect MCP server — skipping"
                        );
                    }
                }
            }
        }

        let subagent_names: HashSet<String> =
            BuiltinTools::subagent_tool_names().into_iter().collect();

        Self {
            builtins,
            mcp: Arc::new(Mutex::new(mcp_executor)),
            mcp_tool_defs,
            builtin_names,
            subagent_names,
        }
    }

    /// All tool definitions to advertise to the LLM (built-ins + MCP + sub-agent).
    pub fn all_tool_defs(&self) -> Vec<Tool> {
        let mut tools = self.builtins.tool_defs();
        tools.extend(BuiltinTools::subagent_tool_defs());
        tools.extend_from_slice(&self.mcp_tool_defs);
        tools
    }

    /// Execute a tool by name, dispatching to built-ins or MCP.
    #[allow(dead_code)]
    pub async fn call(&self, name: &str, arguments: serde_json::Value) -> String {
        if self.builtin_names.contains(name) {
            self.builtins.execute(name, arguments).await
        } else {
            let mut mcp = self.mcp.lock().await;
            match mcp.execute(name, arguments).await {
                Ok(r) if r.success => r.text,
                Ok(r) => format!("[error] tool '{}' failed: {}", name, r.text),
                Err(e) => format!("[error] tool '{}' error: {}", name, e),
            }
        }
    }

    /// Shut down all MCP connections.
    pub async fn shutdown(&self) {
        let mut mcp = self.mcp.lock().await;
        if let Err(e) = mcp.shutdown_all().await {
            tracing::warn!(error = %e, "Error shutting down MCP servers");
        }
    }
}

// ─── Sub-agent tool executor ─────────────────────────────────────────────────

use bevy_ecs::prelude::Entity;
use leviath_core::Blueprint;
use leviath_runtime::{
    AgentEngine, AgentPool, AgentState, AgentStatus, CancellationToken, ContextWindow, ParentRef,
    SubAgentChildren,
};
use tokio::sync::RwLock;

/// Shared state for sub-agent tool execution.
///
/// Wraps an `Arc<RwLock<AgentEngine>>` plus lookup tables so that the tool
/// executor closure can spawn/query/kill child agents.
#[derive(Clone)]
#[allow(dead_code)]
pub struct SubAgentExecutor {
    /// The shared engine — the tool executor needs mutable access to spawn
    /// entities. Using RwLock so multiple reads can happen concurrently.
    engine: Arc<RwLock<AgentEngine>>,

    /// Blueprint registry: name → blueprint, loaded from installed agents
    blueprints: Arc<std::sync::RwLock<HashMap<String, Blueprint>>>,

    /// Agent ID → Entity lookup (all agents, including sub-agents)
    agent_entities: Arc<std::sync::RwLock<HashMap<String, Entity>>>,

    /// Agent pools keyed by blueprint name for auto-numbering
    pools: Arc<std::sync::RwLock<HashMap<String, AgentPool>>>,
}

#[allow(dead_code)]
impl SubAgentExecutor {
    /// Create a new sub-agent executor.
    pub fn new(engine: Arc<RwLock<AgentEngine>>) -> Self {
        Self {
            engine,
            blueprints: Arc::new(std::sync::RwLock::new(HashMap::new())),
            agent_entities: Arc::new(std::sync::RwLock::new(HashMap::new())),
            pools: Arc::new(std::sync::RwLock::new(HashMap::new())),
        }
    }

    /// Register a blueprint so sub-agents can be spawned from it.
    pub fn register_blueprint(&self, blueprint: Blueprint) {
        let name = blueprint.name.clone();
        {
            let mut pools = self.pools.write().unwrap();
            if !pools.contains_key(&name) {
                pools.insert(name.clone(), AgentPool::new(blueprint.clone()));
            }
        }
        self.blueprints.write().unwrap().insert(name, blueprint);
    }

    /// Register an existing agent entity (e.g. the root agent).
    pub fn register_agent(&self, agent_id: String, entity: Entity) {
        self.agent_entities
            .write()
            .unwrap()
            .insert(agent_id, entity);
    }

    /// Execute a sub-agent tool call, returning the result string.
    pub async fn execute(
        &self,
        tool_name: &str,
        args: &serde_json::Value,
        caller_agent_id: &str,
        caller_entity: Entity,
        caller_depth: usize,
        max_depth: usize,
    ) -> String {
        match tool_name {
            "spawn_agent" => {
                self.exec_spawn(
                    args,
                    caller_agent_id,
                    caller_entity,
                    caller_depth,
                    max_depth,
                )
                .await
            }
            "check_agent" => self.exec_check(args, caller_agent_id).await,
            "wait_for_agent" => self.exec_wait(args, caller_agent_id).await,
            "send_to_agent" => self.exec_send(args).await,
            "kill_agent" => self.exec_kill(args, caller_agent_id).await,
            _ => format!("[error] Unknown sub-agent tool: {}", tool_name),
        }
    }

    async fn exec_spawn(
        &self,
        args: &serde_json::Value,
        caller_agent_id: &str,
        caller_entity: Entity,
        caller_depth: usize,
        max_depth: usize,
    ) -> String {
        let blueprint_name = match args.get("blueprint").and_then(|v| v.as_str()) {
            Some(n) => n.to_string(),
            None => return "[error] missing 'blueprint' argument".to_string(),
        };
        let task = match args.get("task").and_then(|v| v.as_str()) {
            Some(t) => t.to_string(),
            None => return "[error] missing 'task' argument".to_string(),
        };
        let _wait = args.get("wait").and_then(|v| v.as_bool()).unwrap_or(false);
        let seed_context = args
            .get("seed_context")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string());

        // Depth validation
        let child_depth = caller_depth + 1;
        if child_depth > max_depth {
            return format!(
                "[error] Cannot spawn sub-agent: depth {} exceeds max depth {}",
                child_depth, max_depth
            );
        }

        // Check blueprint exists
        let blueprint = {
            let bps = self.blueprints.read().unwrap();
            match bps.get(&blueprint_name) {
                Some(bp) => bp.clone(),
                None => {
                    return format!(
                        "[error] Blueprint '{}' not found. Register it first.",
                        blueprint_name
                    )
                }
            }
        };

        // Spawn the child agent entity
        let child_agent_id = {
            let mut pools = self.pools.write().unwrap();
            let pool = pools
                .entry(blueprint_name.clone())
                .or_insert_with(|| AgentPool::new(blueprint.clone()));
            let mut engine = self.engine.blocking_write();
            pool.spawn_agent(engine.world_mut())
        };

        let child_entity = {
            let pools = self.pools.read().unwrap();
            match pools
                .get(&blueprint_name)
                .and_then(|p| p.get_agent(&child_agent_id))
            {
                Some(e) => e,
                None => return "[error] Failed to get spawned child entity".to_string(),
            }
        };

        // Register in our lookup
        self.agent_entities
            .write()
            .unwrap()
            .insert(child_agent_id.clone(), child_entity);

        // Attach ParentRef and SubAgentChildren components
        {
            let mut engine = self.engine.blocking_write();

            // Add ParentRef to child
            engine
                .world_mut()
                .entity_mut(child_entity)
                .insert(ParentRef {
                    parent_entity: caller_entity,
                    parent_agent_id: caller_agent_id.to_string(),
                    depth: child_depth,
                });

            // Add/update SubAgentChildren on parent
            if engine
                .world()
                .get::<SubAgentChildren>(caller_entity)
                .is_some()
            {
                if let Some(mut children) = engine
                    .world_mut()
                    .get_mut::<SubAgentChildren>(caller_entity)
                {
                    children.children.push(child_entity);
                }
            } else {
                engine
                    .world_mut()
                    .entity_mut(caller_entity)
                    .insert(SubAgentChildren {
                        children: vec![child_entity],
                        max_child_depth: max_depth,
                    });
            }

            // Update parent's AgentState
            if let Some(mut state) = engine.world_mut().get_mut::<AgentState>(caller_entity) {
                state.spawned_children_ids.push(child_agent_id.clone());
            }

            // Inject seed context if provided
            if let Some(seed) = &seed_context {
                if let Some(mut window) = engine.world_mut().get_mut::<ContextWindow>(child_entity)
                {
                    let tokens = seed.len() / 4 + 1;
                    let pinned_name = window
                        .regions
                        .iter()
                        .find(|r| matches!(r.kind, leviath_core::RegionKind::Pinned))
                        .map(|r| r.name.clone());
                    if let Some(name) = pinned_name {
                        let _ = window.add_to_region(&name, seed.clone(), tokens);
                    }
                }
            }

            // Set child as Active
            if let Some(mut state) = engine.world_mut().get_mut::<AgentState>(child_entity) {
                state.status = AgentStatus::Active;
            }
        }

        tracing::info!(
            parent = %caller_agent_id,
            child = %child_agent_id,
            blueprint = %blueprint_name,
            depth = child_depth,
            "Spawned sub-agent"
        );

        let _ = task; // Task is used by the caller to set up the child's context
        format!(
            "Spawned sub-agent '{}' (blueprint: {}, depth: {})",
            child_agent_id, blueprint_name, child_depth
        )
    }

    async fn exec_check(&self, args: &serde_json::Value, _caller_agent_id: &str) -> String {
        let agent_id = match args.get("agent_id").and_then(|v| v.as_str()) {
            Some(id) => id,
            None => return "[error] missing 'agent_id' argument".to_string(),
        };

        let entity = {
            let entities = self.agent_entities.read().unwrap();
            match entities.get(agent_id) {
                Some(e) => *e,
                None => return format!("[error] Agent '{}' not found", agent_id),
            }
        };

        let engine = self.engine.blocking_read();
        let world = engine.world();

        let status = match world.get::<AgentState>(entity) {
            Some(state) => match &state.status {
                AgentStatus::Active => "active".to_string(),
                AgentStatus::Waiting => "waiting".to_string(),
                AgentStatus::Complete => "complete".to_string(),
                AgentStatus::Error { message } => format!("error: {}", message),
                AgentStatus::Cancelled => "cancelled".to_string(),
                AgentStatus::Idle => "idle".to_string(),
            },
            None => return format!("[error] Agent '{}' entity has no state", agent_id),
        };

        // If complete, try to get the last response from context
        let result = if status == "complete" {
            if let Some(window) = world.get::<ContextWindow>(entity) {
                window
                    .get_region("conversation")
                    .and_then(|r| r.content.last())
                    .map(|e| e.content.clone())
            } else {
                None
            }
        } else {
            None
        };

        match result {
            Some(content) => format!("Status: {}\nResult: {}", status, content),
            None => format!("Status: {}", status),
        }
    }

    async fn exec_wait(&self, args: &serde_json::Value, caller_agent_id: &str) -> String {
        let agent_id = match args.get("agent_id").and_then(|v| v.as_str()) {
            Some(id) => id.to_string(),
            None => return "[error] missing 'agent_id' argument".to_string(),
        };

        let entity = {
            let entities = self.agent_entities.read().unwrap();
            match entities.get(&agent_id) {
                Some(e) => *e,
                None => return format!("[error] Agent '{}' not found", agent_id),
            }
        };

        // Set the parent's pending_wait
        {
            let caller_entity = {
                let entities = self.agent_entities.read().unwrap();
                entities.get(caller_agent_id).copied()
            };
            if let Some(ce) = caller_entity {
                let mut engine = self.engine.blocking_write();
                if let Some(mut state) = engine.world_mut().get_mut::<AgentState>(ce) {
                    state.pending_wait = Some(agent_id.clone());
                }
            }
        }

        // Poll until child completes (check every 500ms)
        loop {
            {
                let engine = self.engine.blocking_read();
                let world = engine.world();
                if let Some(state) = world.get::<AgentState>(entity) {
                    match &state.status {
                        AgentStatus::Complete => {
                            // Clear pending_wait on parent
                            drop(engine);
                            let caller_entity = {
                                let entities = self.agent_entities.read().unwrap();
                                entities.get(caller_agent_id).copied()
                            };
                            if let Some(ce) = caller_entity {
                                let mut eng = self.engine.blocking_write();
                                if let Some(mut pstate) = eng.world_mut().get_mut::<AgentState>(ce)
                                {
                                    pstate.pending_wait = None;
                                }
                            }

                            // Get final result
                            let eng = self.engine.blocking_read();
                            let result = eng
                                .world()
                                .get::<ContextWindow>(entity)
                                .and_then(|w| {
                                    w.get_region("conversation")
                                        .and_then(|r| r.content.last())
                                        .map(|e| e.content.clone())
                                })
                                .unwrap_or_else(|| "(no result)".to_string());
                            return format!("Agent '{}' completed.\nResult: {}", agent_id, result);
                        }
                        AgentStatus::Error { message } => {
                            return format!("Agent '{}' failed with error: {}", agent_id, message);
                        }
                        AgentStatus::Cancelled => {
                            return format!("Agent '{}' was cancelled", agent_id);
                        }
                        _ => {}
                    }
                } else {
                    return format!("[error] Agent '{}' entity no longer exists", agent_id);
                }
            }
            tokio::time::sleep(std::time::Duration::from_millis(500)).await;
        }
    }

    async fn exec_send(&self, args: &serde_json::Value) -> String {
        let agent_id = match args.get("agent_id").and_then(|v| v.as_str()) {
            Some(id) => id.to_string(),
            None => return "[error] missing 'agent_id' argument".to_string(),
        };
        let message = match args.get("message").and_then(|v| v.as_str()) {
            Some(m) => m.to_string(),
            None => return "[error] missing 'message' argument".to_string(),
        };
        let target_region = args
            .get("target_region")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string());

        let engine = self.engine.blocking_read();
        let msg = leviath_runtime::AgentMessage {
            agent_id: agent_id.clone(),
            content: message,
            target_region,
            priority: 0,
        };
        match engine.send_message(msg) {
            Ok(()) => format!("Message sent to '{}'", agent_id),
            Err(e) => format!("[error] Failed to send message: {}", e),
        }
    }

    async fn exec_kill(&self, args: &serde_json::Value, _caller_agent_id: &str) -> String {
        let agent_id = match args.get("agent_id").and_then(|v| v.as_str()) {
            Some(id) => id.to_string(),
            None => return "[error] missing 'agent_id' argument".to_string(),
        };

        let entity = {
            let entities = self.agent_entities.read().unwrap();
            match entities.get(&agent_id) {
                Some(e) => *e,
                None => return format!("[error] Agent '{}' not found", agent_id),
            }
        };

        // Cascade kill: collect all descendants first
        let mut to_kill = vec![entity];
        {
            let engine = self.engine.blocking_read();
            let world = engine.world();
            let mut i = 0;
            while i < to_kill.len() {
                let e = to_kill[i];
                if let Some(children) = world.get::<SubAgentChildren>(e) {
                    to_kill.extend_from_slice(&children.children);
                }
                i += 1;
            }
        }

        // Cancel all
        {
            let mut engine = self.engine.blocking_write();
            for e in &to_kill {
                if let Some(token) = engine.world().get::<CancellationToken>(*e) {
                    token.cancel();
                }
                if let Some(mut state) = engine.world_mut().get_mut::<AgentState>(*e) {
                    state.status = AgentStatus::Cancelled;
                }
            }
        }

        let count = to_kill.len();
        if count == 1 {
            format!("Killed agent '{}'", agent_id)
        } else {
            format!(
                "Killed agent '{}' and {} descendant(s)",
                agent_id,
                count - 1
            )
        }
    }
}

// ─── Tool policy resolution ───────────────────────────────────────────────────

/// Built-in Claude Code-style defaults: read-only tools auto-allow, everything
/// else requires approval.
pub fn default_tool_policy(tool_name: &str, is_builtin: bool) -> ToolPolicy {
    match tool_name {
        "read_file" | "list_dir" => ToolPolicy::Allow,
        "write_file" | "edit_file" | "bash" => ToolPolicy::Ask,
        _ => {
            // All other tools (built-in or MCP) default to Ask
            let _ = is_builtin;
            ToolPolicy::Ask
        }
    }
}

/// Resolve the effective policy for a tool call, narrowest scope first.
///
/// Precedence (first match wins):
/// 1. `launch_overrides` — from `--allow`/`--ask`/`--deny` / `--yolo` flags
/// 2. `stage_permissions` — `[stages.x.tool_permissions]` in agent.leviath
/// 3. `agent_permissions` — `[tool_permissions]` in agent.leviath
/// 4. `global_permissions` — `[tool_permissions]` in `~/.leviath/config.toml`
/// 5. Built-in defaults
pub fn resolve_policy(
    tool_name: &str,
    is_builtin: bool,
    launch_overrides: &HashMap<String, ToolPolicy>,
    stage_permissions: &HashMap<String, String>,
    agent_permissions: &HashMap<String, String>,
    global_permissions: &HashMap<String, ToolPolicy>,
) -> ToolPolicy {
    // 1. Launch overrides (highest priority)
    if let Some(p) = launch_overrides.get(tool_name) {
        return *p;
    }
    // Wildcard launch allow ("--yolo")
    if let Some(p) = launch_overrides.get("*") {
        return *p;
    }

    // 2. Stage-level (from blueprint string map "allow"/"ask"/"deny")
    if let Some(s) = stage_permissions.get(tool_name) {
        return parse_policy_str(s);
    }

    // 3. Agent-level
    if let Some(s) = agent_permissions.get(tool_name) {
        return parse_policy_str(s);
    }

    // 4. Global config
    if let Some(p) = global_permissions.get(tool_name) {
        return *p;
    }

    // 5. Built-in defaults
    default_tool_policy(tool_name, is_builtin)
}

fn parse_policy_str(s: &str) -> ToolPolicy {
    match s.to_lowercase().as_str() {
        "allow" => ToolPolicy::Allow,
        "deny" => ToolPolicy::Deny,
        _ => ToolPolicy::Ask,
    }
}

#[cfg(test)]
mod policy_tests {
    use super::*;

    #[test]
    fn test_default_policy_read_file() {
        assert_eq!(default_tool_policy("read_file", true), ToolPolicy::Allow);
        assert_eq!(default_tool_policy("list_dir", true), ToolPolicy::Allow);
    }

    #[test]
    fn test_default_policy_write_tools() {
        assert_eq!(default_tool_policy("write_file", true), ToolPolicy::Ask);
        assert_eq!(default_tool_policy("edit_file", true), ToolPolicy::Ask);
        assert_eq!(default_tool_policy("bash", true), ToolPolicy::Ask);
    }

    #[test]
    fn test_resolve_policy_launch_override_wins() {
        let mut launch = HashMap::new();
        launch.insert("bash".to_string(), ToolPolicy::Allow);
        let policy = resolve_policy(
            "bash",
            true,
            &launch,
            &HashMap::new(),
            &HashMap::new(),
            &HashMap::new(),
        );
        assert_eq!(policy, ToolPolicy::Allow);
    }

    #[test]
    fn test_resolve_policy_yolo_wins() {
        let mut launch = HashMap::new();
        launch.insert("*".to_string(), ToolPolicy::Allow);
        let policy = resolve_policy(
            "bash",
            true,
            &launch,
            &HashMap::new(),
            &HashMap::new(),
            &HashMap::new(),
        );
        assert_eq!(policy, ToolPolicy::Allow);
    }

    #[test]
    fn test_resolve_policy_stage_beats_global() {
        let mut stage = HashMap::new();
        stage.insert("bash".to_string(), "allow".to_string());
        let mut global = HashMap::new();
        global.insert("bash".to_string(), ToolPolicy::Deny);
        let policy = resolve_policy(
            "bash",
            true,
            &HashMap::new(),
            &stage,
            &HashMap::new(),
            &global,
        );
        assert_eq!(policy, ToolPolicy::Allow);
    }

    #[test]
    fn test_resolve_policy_falls_through_to_default() {
        let policy = resolve_policy(
            "bash",
            true,
            &HashMap::new(),
            &HashMap::new(),
            &HashMap::new(),
            &HashMap::new(),
        );
        assert_eq!(policy, ToolPolicy::Ask);
    }
}

//! Agent blueprints and stage definitions.
//!
//! A blueprint is the complete definition of an agent type, including its
//! execution stages, model selection, tool access, and context layout.
//! Blueprints are typically defined in `leviath.toml` files and can be
//! shared, installed, and versioned.

use crate::error::ValidationError;
use crate::layout::ContextLayout;
use crate::lifecycle::CompactionConfig;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

/// An agent blueprint — the complete definition of an agent type.
///
/// Includes stages, model selection, tools, AND context layout. A blueprint
/// defines everything needed to instantiate and run an agent with specific
/// capabilities and memory structure.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Blueprint {
    /// Unique name for this agent type
    pub name: String,

    /// Human-readable description
    pub description: String,

    /// Execution stages (e.g., analyze → implement → review)
    pub stages: Vec<Stage>,

    /// Context window layout defining memory regions
    pub context_layout: ContextLayout,

    /// Tool filters controlling which tools are available
    pub tools: Vec<ToolFilter>,

    /// Context transforms for inter-agent communication
    pub transforms: Vec<ContextTransform>,

    /// Version of this blueprint
    pub version: String,

    /// Configuration for LLM-based compaction
    pub compaction_config: Option<CompactionConfig>,

    /// Maximum depth of the sub-agent tree (default: 3)
    pub max_child_depth: Option<usize>,

    /// Which stage to start from (default: first defined)
    pub entry_stage: Option<String>,

    /// Additional metadata
    pub metadata: HashMap<String, serde_json::Value>,
}

impl Blueprint {
    /// Create a new blueprint with the specified configuration.
    pub fn new(
        name: String,
        description: String,
        stages: Vec<Stage>,
        context_layout: ContextLayout,
    ) -> Self {
        Self {
            name,
            description,
            stages,
            context_layout,
            tools: Vec::new(),
            transforms: Vec::new(),
            version: "0.1.0".to_string(),
            compaction_config: None,
            max_child_depth: None,
            entry_stage: None,
            metadata: HashMap::new(),
        }
    }

    /// Add tool filters to this blueprint.
    pub fn with_tools(mut self, tools: Vec<ToolFilter>) -> Self {
        self.tools = tools;
        self
    }

    /// Add context transforms to this blueprint.
    pub fn with_transforms(mut self, transforms: Vec<ContextTransform>) -> Self {
        self.transforms = transforms;
        self
    }

    /// Set the version of this blueprint.
    pub fn with_version(mut self, version: String) -> Self {
        self.version = version;
        self
    }

    /// Validate that the blueprint is well-formed.
    pub fn validate(&self) -> std::result::Result<(), ValidationError> {
        // Validate context layout
        self.context_layout.validate()?;

        // Check that all stages have valid configurations
        for stage in &self.stages {
            stage.validate()?;
        }

        // Validate transforms reference real regions
        for transform in &self.transforms {
            transform.validate(&self.context_layout)?;
        }

        // Graph validation
        self.validate_graph()?;

        Ok(())
    }

    /// Validate stage graph constraints.
    fn validate_graph(&self) -> std::result::Result<(), ValidationError> {
        let stage_names: std::collections::HashSet<&str> =
            self.stages.iter().map(|s| s.name.as_str()).collect();

        // Entry stage must exist if set
        if let Some(ref entry) = self.entry_stage {
            if !stage_names.contains(entry.as_str()) {
                return Err(ValidationError::Graph(format!(
                    "entry_stage '{}' does not match any defined stage",
                    entry
                )));
            }
        }

        let has_any_transitions = self.stages.iter().any(|s| s.transitions.is_some());
        if !has_any_transitions {
            // Pure linear mode — no graph validation needed
            return Ok(());
        }

        // All transition targets must exist
        for stage in &self.stages {
            if let Some(ref transitions) = stage.transitions {
                for target_name in transitions.keys() {
                    if !stage_names.contains(target_name.as_str()) {
                        return Err(ValidationError::Transition {
                            from: stage.name.clone(),
                            to: target_name.clone(),
                            message: "target stage does not exist".to_string(),
                        });
                    }
                }

                // Self-loop safety: stages that transition to themselves need max_revisits
                if transitions.contains_key(&stage.name) && stage.max_revisits.is_none() {
                    return Err(ValidationError::Stage {
                        stage: stage.name.clone(),
                        message: "self-loop transition requires max_revisits".to_string(),
                    });
                }
            }
        }

        // At least one terminal path must exist (a stage with no outgoing transitions,
        // or with only conditional transitions that may not fire)
        let entry = self.resolve_entry_stage_name();
        let has_terminal = self.has_terminal_path(&entry, &mut std::collections::HashSet::new());
        if !has_terminal {
            return Err(ValidationError::Graph(
                "no terminal path exists from entry stage — agent would never complete".to_string(),
            ));
        }

        Ok(())
    }

    /// Resolve the entry stage name.
    pub fn resolve_entry_stage_name(&self) -> String {
        self.entry_stage.clone().unwrap_or_else(|| {
            self.stages
                .first()
                .map(|s| s.name.clone())
                .unwrap_or_default()
        })
    }

    /// Check if there is a terminal path reachable from `stage_name`.
    fn has_terminal_path(
        &self,
        stage_name: &str,
        visited: &mut std::collections::HashSet<String>,
    ) -> bool {
        if visited.contains(stage_name) {
            return false;
        }
        visited.insert(stage_name.to_string());

        let stage = self.stages.iter().find(|s| s.name == stage_name);
        let stage = match stage {
            Some(s) => s,
            None => return false,
        };

        match &stage.transitions {
            None => {
                // Linear mode: check if there's a next stage by index
                let idx = self
                    .stages
                    .iter()
                    .position(|s| s.name == stage_name)
                    .unwrap_or(0);
                if idx + 1 >= self.stages.len() {
                    return true; // terminal
                }
                self.has_terminal_path(&self.stages[idx + 1].name, visited)
            }
            Some(transitions) => {
                if transitions.is_empty() {
                    return true; // terminal stage
                }
                // Check if any transition leads to a terminal
                for target in transitions.keys() {
                    if self.has_terminal_path(target, visited) {
                        return true;
                    }
                }
                // If all targets are exhaustible (already visited + have max_revisits),
                // the stage will eventually have zero available edges → terminal
                let all_exhaustible = transitions.keys().all(|target| {
                    if !visited.contains(target) {
                        return false;
                    }
                    self.stages
                        .iter()
                        .find(|s| s.name == *target)
                        .map(|s| s.max_revisits.is_some())
                        .unwrap_or(false)
                });
                all_exhaustible
            }
        }
    }

    /// Find a stage by name.
    pub fn find_stage(&self, name: &str) -> Option<&Stage> {
        self.stages.iter().find(|s| s.name == name)
    }
}

/// Interaction mode for a stage.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub enum StageMode {
    /// Runs without user input, fully autonomous
    #[default]
    Autonomous,

    /// Requires user input before starting
    Interactive,

    /// Can receive input at defined points during execution
    InteractivePoints {
        /// Points where user input can be requested
        points: Vec<InteractionPoint>,
    },
}

/// Style of interaction at an interaction point.
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum InteractionStyle {
    /// Free-form text answer (default).
    #[default]
    FreeText,
    /// User picks one option from a list.
    MultipleChoice,
    /// Simple yes/no confirmation.
    Confirm,
}

/// A point where a stage can request user input.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InteractionPoint {
    /// Unique name for this interaction point
    pub name: String,

    /// Prompt to show the user
    pub prompt: String,

    /// Whether input is required (vs optional)
    pub required: bool,

    /// Style of interaction (free text, multiple choice, confirm)
    #[serde(default)]
    pub style: InteractionStyle,

    /// Options for MultipleChoice style
    #[serde(default)]
    pub options: Vec<String>,
}

/// Configuration for routing tool results to specific context window regions.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolResultRouting {
    /// Default region for tool results (default: "tool_results")
    pub default_region: String,
    /// Per-tool overrides: tool_name → region_name
    pub tool_overrides: HashMap<String, String>,
    /// Whether to keep tool results (true) or discard after use (false)
    pub persist: bool,
    /// Max tokens per tool result (truncate if larger)
    pub max_result_tokens: Option<usize>,
}

impl Default for ToolResultRouting {
    fn default() -> Self {
        Self {
            default_region: "tool_results".to_string(),
            tool_overrides: HashMap::new(),
            persist: true,
            max_result_tokens: None,
        }
    }
}

/// A single execution stage in an agent's workflow.
///
/// Stages allow an agent to use different models or configurations for
/// different phases of work. For example, a coding agent might have:
/// - Analyze stage: fast model for understanding requirements
/// - Implement stage: powerful model for code generation
/// - Review stage: critique model for checking quality
///
/// Each stage can have its own context layout (memory structure), allowing
/// different stages to have different region configurations optimized for
/// their specific needs.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Stage {
    /// Name of this stage
    pub name: String,

    /// Description of what this stage does
    pub description: Option<String>,

    /// Model to use for this stage
    pub model: ModelConfig,

    /// Which tools are available in this stage
    pub available_tools: Vec<String>,

    /// Maximum iterations for this stage
    pub max_iterations: Option<usize>,

    /// Interaction mode (autonomous or interactive)
    #[serde(default)]
    pub mode: StageMode,

    /// Optional stage-specific context layout
    /// If None, uses the blueprint's global layout
    pub context_layout: Option<ContextLayout>,

    /// Custom configuration for this stage
    pub config: HashMap<String, serde_json::Value>,

    /// Optional routing configuration for tool results
    pub tool_result_routing: Option<ToolResultRouting>,

    /// Per-tool permission overrides for this stage.
    /// Keys: tool name. Values: "allow" | "ask" | "deny".
    /// Narrower than agent-level, wider than launch flags.
    #[serde(default)]
    pub tool_permissions: HashMap<String, String>,

    /// If true, don't advance to the next stage until all children spawned
    /// during this stage have completed.
    #[serde(default)]
    pub requires_children: bool,

    /// Directed transitions from this stage (None = linear/next-in-list)
    pub transitions: Option<HashMap<String, TransitionEdge>>,

    /// Max times this stage can be re-entered (revisits, not counting first visit)
    pub max_revisits: Option<usize>,

    /// Custom prompt for transition decisions (overrides default)
    pub transition_prompt: Option<String>,

    /// Whether this stage accepts mid-run user messages.
    /// When true, messages sent to the agent are injected into context
    /// between inference calls. Default: true.
    #[serde(default = "default_true")]
    pub accepts_messages: bool,
}

/// Default value for bool fields that should default to true.
fn default_true() -> bool {
    true
}

impl Stage {
    /// Create a new stage with the specified configuration.
    pub fn new(name: String, model: ModelConfig) -> Self {
        Self {
            name,
            description: None,
            model,
            available_tools: Vec::new(),
            max_iterations: None,
            mode: StageMode::Autonomous,
            context_layout: None,
            config: HashMap::new(),
            tool_result_routing: None,
            tool_permissions: HashMap::new(),
            requires_children: false,
            transitions: None,
            max_revisits: None,
            transition_prompt: None,
            accepts_messages: true,
        }
    }

    /// Add tools to this stage.
    pub fn with_tools(mut self, tools: Vec<String>) -> Self {
        self.available_tools = tools;
        self
    }

    /// Set the interaction mode for this stage.
    pub fn with_mode(mut self, mode: StageMode) -> Self {
        self.mode = mode;
        self
    }

    /// Set a stage-specific context layout.
    pub fn with_context_layout(mut self, layout: ContextLayout) -> Self {
        self.context_layout = Some(layout);
        self
    }

    /// Set the description for this stage.
    pub fn with_description(mut self, description: String) -> Self {
        self.description = Some(description);
        self
    }

    /// Validate that this stage is well-formed.
    fn validate(&self) -> std::result::Result<(), ValidationError> {
        if self.name.is_empty() {
            return Err(ValidationError::Stage {
                stage: "(empty)".to_string(),
                message: "stage name cannot be empty".to_string(),
            });
        }

        // Validate stage-specific context layout if present
        if let Some(layout) = &self.context_layout {
            layout.validate()?;
        }

        Ok(())
    }
}

/// Model configuration for a stage.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ModelConfig {
    /// Provider name (e.g., "anthropic", "openai")
    pub provider: String,

    /// Model identifier (e.g., "claude-sonnet-4-6")
    pub model: String,

    /// Optional parameters for this model
    pub parameters: HashMap<String, serde_json::Value>,
}

impl ModelConfig {
    /// Create a new model configuration.
    pub fn new(provider: String, model: String) -> Self {
        Self {
            provider,
            model,
            parameters: HashMap::new(),
        }
    }
}

/// Filter controlling which tools an agent can access.
///
/// Tool filters can include or exclude specific tools, tool categories,
/// or apply more complex rules for tool access.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolFilter {
    /// Name or pattern for tools
    pub pattern: String,

    /// Whether this is an include or exclude filter
    pub filter_type: FilterType,

    /// Optional stage restriction
    pub stage: Option<String>,
}

/// Type of tool filter.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum FilterType {
    /// Include matching tools
    Include,
    /// Exclude matching tools
    Exclude,
}

/// Context transform for converting between agent types.
///
/// When spawning a sub-agent with a different blueprint, transforms define
/// how to map regions from the parent agent's context to the child agent's
/// context. This enables smooth handoffs between agents with different
/// memory structures.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContextTransform {
    /// Source blueprint name
    pub from_blueprint: String,

    /// Target blueprint name
    pub to_blueprint: String,

    /// Region mapping rules
    pub mappings: Vec<RegionMapping>,
}

impl ContextTransform {
    /// Validate that this transform references valid regions.
    fn validate(&self, layout: &ContextLayout) -> std::result::Result<(), ValidationError> {
        for mapping in &self.mappings {
            // We can only validate target regions against the current layout
            // (source regions belong to a different blueprint)
            if layout.get_region(&mapping.to_region).is_none() {
                return Err(ValidationError::Region {
                    region: mapping.to_region.clone(),
                    message: "transform target region not found in layout".to_string(),
                });
            }
        }
        Ok(())
    }
}

/// Mapping rule for a single region in a context transform.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RegionMapping {
    /// Source region name
    pub from_region: String,

    /// Target region name
    pub to_region: String,

    /// Optional transformation to apply to content
    pub transform: Option<ContentTransform>,
}

/// A directed transition edge from one stage to another.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TransitionEdge {
    /// Target stage name (derived from the HashMap key during parsing)
    pub target: String,

    /// When this edge is available
    #[serde(default)]
    pub condition: TransitionCondition,

    /// Human-readable hint for the LLM
    pub hint: Option<String>,

    /// How context transforms when crossing this edge
    #[serde(default)]
    pub transform: EdgeTransform,
}

/// Condition that determines when a transition edge is available.
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum TransitionCondition {
    /// Always available (LLM chooses)
    #[default]
    Always,
    /// Only on error
    Error,
    /// Only when max_iterations hit
    MaxIterations,
    /// LLM picks from available transitions (default for multi-transition stages)
    LlmChoice,
    /// Custom condition string (future: Rhai expression)
    Custom(String),
}

/// How context transforms when crossing a transition edge.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EdgeTransform {
    /// Copy everything as-is (default for single-transition linear stages)
    #[default]
    Direct,

    /// Clear stage-specific regions, keep pinned/system
    Clear,

    /// LLM-compact stage content into summary
    Compact {
        #[serde(default)]
        prompt: Option<String>,
    },

    /// Per-region rules
    Custom {
        carry: Vec<String>,
        compact: Vec<String>,
        clear: Vec<String>,
        compact_prompt: Option<String>,
    },
}

/// Result of running a stage, used for transition condition evaluation.
#[derive(Debug, Clone, PartialEq)]
pub enum StageResult {
    /// Stage completed normally
    Success,
    /// Stage encountered an error
    Error,
    /// Stage hit max_iterations without LLM signaling completion
    MaxIterations,
}

/// Content transformation type.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ContentTransform {
    /// Copy content as-is
    Direct,

    /// Summarize content to fit target region
    Summarize,

    /// Extract specific fields
    Extract { fields: Vec<String> },

    /// Custom transformation
    Custom { function: String },
}

