            ("SSH_PRIVATE_KEY".to_string(), "key789".to_string()),
            ("MY_API_SECRET".to_string(), "sec000".to_string()),
            ("SECRET_KEY_BASE".to_string(), "skb111".to_string()),
        ];

        let filtered = MCPClient::filter_env(&vars);

