    #[test]
    fn test_provider_registry() {
        let mut registry = ProviderRegistry::new();
        assert!(!registry.has("anthropic"));

        registry.register(
            "anthropic".to_string(),
            Arc::new(leviath_providers::AnthropicProvider::new(
                "test-key".to_string(),
            )),
        );
        assert!(registry.has("anthropic"));
        assert!(registry.get("anthropic").is_some());
        assert_eq!(registry.provider_names().len(), 1);
    }

    #[test]
    fn test_engine_tick() {
        let mut engine = AgentEngine::new();
        // Should not panic with no entities
        engine.tick();
    }

    #[test]
    fn test_message_sender() {
        let engine = AgentEngine::new();
        let sender = engine.get_message_sender();
        // Should be able to send a message (will be queued)
        let msg = crate::components::AgentMessage {
            agent_id: "test-1".to_string(),
            content: "hello".to_string(),
            target_region: None,
            priority: 0,
        };
        assert!(sender.send(msg).is_ok());
    }

    #[test]
    fn test_process_messages_no_agents() {
        let mut engine = AgentEngine::new();
        // Send a message
        let msg = crate::components::AgentMessage {
            agent_id: "nonexistent".to_string(),
            content: "hello".to_string(),
            target_region: None,
            priority: 0,
        };
        engine.send_message(msg).unwrap();
        // Should not panic even with no matching agents
        engine.process_messages();
    }

    #[test]
    fn test_cancel_nonexistent_agent() {
        let mut engine = AgentEngine::new();
        let result = engine.cancel_agent("nonexistent");
        assert!(result.is_err());
    }

    #[test]
    fn test_tool_result_routing_config_default() {
        let config = ToolResultRoutingConfig::default();
        assert_eq!(config.default_region, "tool_results");
        assert!(config.persist);
        assert!(config.max_result_tokens.is_none());
        assert!(config.tool_overrides.is_empty());
    }

    #[test]
    fn test_deliver_inbox_messages_respects_accepts_messages_false() {
        let mut engine = AgentEngine::new();
        let entity = engine
            .world_mut()
            .spawn((
                AgentState {
                    agent_id: "test-agent".to_string(),
                    current_stage: "report".to_string(),
                    iteration: 0,
                    status: AgentStatus::Active,
                    spawned_children_ids: Vec::new(),
                    pending_wait: None,
                    accepts_messages: false,
                },
                MessageInbox::new(),
                {
                    let mut window = ContextWindow::new(10000);
                    window.add_region(leviath_core::Region::new(
                        "conversation".to_string(),
                        leviath_core::RegionKind::SlidingWindow { max_items: 50 },
                        8000,
                    ));
                    window
                },
            ))
            .id();

        // Send a message
        engine
            .send_message(AgentMessage {
                agent_id: "test-agent".to_string(),
                content: "hello".to_string(),
                target_region: None,
                priority: 0,
            })
            .unwrap();

        // Process — should route to inbox but NOT deliver to context
        engine.process_messages();

        // Message should still be in inbox
        let inbox = engine.world().get::<MessageInbox>(entity).unwrap();
        assert_eq!(
            inbox.messages.len(),
            1,
            "message should stay in inbox when accepts_messages=false"
        );

        // Context should be empty
        let window = engine.world().get::<ContextWindow>(entity).unwrap();
        let conv = window.get_region("conversation").unwrap();
        assert!(conv.content.is_empty(), "no messages should be in context");
    }

    #[test]
    fn test_deliver_inbox_messages_delivers_when_accepts_messages_true() {
        let mut engine = AgentEngine::new();
        let entity = engine
            .world_mut()
            .spawn((
                AgentState {
                    agent_id: "test-agent".to_string(),
                    current_stage: "analyze".to_string(),
                    iteration: 0,
                    status: AgentStatus::Active,
                    spawned_children_ids: Vec::new(),
                    pending_wait: None,
                    accepts_messages: true,
                },
                MessageInbox::new(),
                {
                    let mut window = ContextWindow::new(10000);
                    window.add_region(leviath_core::Region::new(
                        "conversation".to_string(),
                        leviath_core::RegionKind::SlidingWindow { max_items: 50 },
                        8000,
                    ));
                    window
                },
            ))
            .id();

        engine
            .send_message(AgentMessage {
                agent_id: "test-agent".to_string(),
                content: "focus on error handling".to_string(),
                target_region: None,
                priority: 0,
            })
            .unwrap();

        engine.process_messages();

        // Message should be delivered to context
        let window = engine.world().get::<ContextWindow>(entity).unwrap();
        let conv = window.get_region("conversation").unwrap();
        assert_eq!(conv.content.len(), 1);
        assert!(
            conv.content[0].content.starts_with("User: "),
            "message should be formatted as 'User: ...' not '[Message]: ...'"
        );
        assert!(conv.content[0].content.contains("focus on error handling"));

        // Inbox should be drained
        let inbox = engine.world().get::<MessageInbox>(entity).unwrap();
        assert!(inbox.messages.is_empty());
    }
}

//! # Leviath Runtime
//!
//! ECS-based agent execution engine using bevy_ecs.
//!
//! The runtime manages agent lifecycle, context window management, task scheduling,
//! and inference execution through a game-loop-inspired architecture where agents
//! are entities and their behaviors are systems.

pub mod components;
pub mod engine;
pub mod pool;
pub mod scheduler;
pub mod systems;

pub use components::{
    AgentMessage, AgentState, AgentStatus, CancellationToken, ContextWindow, EvictionResult,
    InferenceResult, MessageInbox, NeedsCompaction, ParentRef, SubAgentChildren, TaskAssignment,
};
pub use engine::{AgentEngine, ProviderRegistry, ToolResultRoutingConfig};
pub use pool::AgentPool;
pub use scheduler::TaskScheduler;

//! Agent pool management.
//!
//! The pool manages a collection of agent instances, recycling completed agents
//! and spawning new ones as needed. Agents are auto-numbered and tracked.

use crate::components::{AgentState, AgentStatus, CancellationToken, ContextWindow, MessageInbox};
use bevy_ecs::prelude::*;
use leviath_core::Blueprint;
use std::collections::HashMap;

/// Manager for a pool of agents.
///
/// Handles spawning, recycling, and tracking agent instances.
pub struct AgentPool {
    /// Blueprint for agents in this pool
    blueprint: Blueprint,

    /// Counter for auto-numbering agents
    next_id: usize,

    /// Active agent entities
    active_agents: HashMap<String, Entity>,
}

impl AgentPool {
    /// Create a new agent pool for the given blueprint.
    pub fn new(blueprint: Blueprint) -> Self {
        Self {
            blueprint,
            next_id: 1,
            active_agents: HashMap::new(),
        }
    }

    /// Spawn a new agent in the pool.
    ///
    /// Creates an entity with all necessary components based on the blueprint.
    pub fn spawn_agent(&mut self, world: &mut World) -> String {
        let agent_id = format!("{}-{}", self.blueprint.name, self.next_id);
        self.next_id += 1;

        // Create context window from blueprint layout
        let context_window = ContextWindow::new(self.blueprint.context_layout.total_budget_tokens);

        // Create agent state
        let agent_state = AgentState {
            agent_id: agent_id.clone(),
            current_stage: self
                .blueprint
                .stages
                .first()
                .map(|s| s.name.clone())
                .unwrap_or_else(|| "default".to_string()),
            iteration: 0,
            status: AgentStatus::Idle,
            spawned_children_ids: Vec::new(),
            pending_wait: None,
            accepts_messages: true,
        };

        // Spawn entity with components
        let cancellation_token = CancellationToken::new();
        let message_inbox = MessageInbox::new();
        let entity = world
            .spawn((
                agent_state,
                context_window,
                cancellation_token,
                message_inbox,
            ))
            .id();

        self.active_agents.insert(agent_id.clone(), entity);
        tracing::info!(agent_id = %agent_id, "Spawned new agent");

        agent_id
    }

    /// Get the entity for an agent by ID.
    pub fn get_agent(&self, agent_id: &str) -> Option<Entity> {
        self.active_agents.get(agent_id).copied()
    }

    /// Remove an agent from the pool.
    pub fn remove_agent(&mut self, agent_id: &str) {
        self.active_agents.remove(agent_id);
    }

    /// Get the number of active agents.
    pub fn agent_count(&self) -> usize {
        self.active_agents.len()
    }

    /// Get the blueprint for this pool.
    pub fn blueprint(&self) -> &Blueprint {
        &self.blueprint
    }
}

